INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298390, 183316, '1', '6', 145096, 'IRE', 'Kentucky River', '3', '10-1', 63.95, 'p', '80', 22, 'L Morris', 3867, 'Ollie Sangster', NULL, NULL, NULL, 'Improved for quicker ground with an easy victory when landing a handicap by 7l off a mark of 74 over 2m1f at Pontefract last time. Significant jockey booking. Steadily progressive as the trip increases and has more to come as a stayer.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298391, 183316, '2', '3', 133838, 'IRE', 'Simiyann', '5', '10-0', 63.5, 'p', '68', 5191, 'Saffie Osborne', 45, 'Ian Williams', NULL, '9/1', 10.0, 'Scored by a head off 69 at Haydock in May. Ran to form when fourth, beaten 8 1/2l off the same mark last time. Significant jockey booking. A consistent stayer who goes well on a sound surface.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298392, 183316, '3', '1', 126681, 'IRE', 'Hedonista', '5', '9-12', 62.55, 'pt', '66', 5641, 'Elizabeth Gale', 528, 'B J Llewellyn', NULL, '16/1', 17.0, 'Below form in first-time cheekpieces when comfortably held in a handicap over 1m6f here last time. Generally out of form and struggling of late, though now back below her last winning mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298393, 183316, '4', '4', 101576, 'FR', 'Masterdream', '8', '9-9', 61.2, 'pt', '63', 5195, 'Callum Hutchinson', 312, 'N P Mulholland', '2nd', '5/1', 6.0, 'Travelled well and improved down in grade with a positive ride when scoring by 9l off 97 over 2m7f at Worcester on his penultimate start. A veteran who needs a sound surface. Back to form over hurdles latest and could transfer that back to the flat.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298394, 183316, '5', '2', 140532, 'GB', 'Navid', '3', '9-6', 59.85, 'p', '71', 4172, 'Finley Marsh', 4104, 'Harry Charlton', '1st', '6/5', 2.2, 'Improved up in trip under a positive ride when landing a handicap by 2l off 63 over 1m6f at Salisbury last time. Trainer in form. Progressing as the trip increases, quick ground suits, and he has more to come as a stayer.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298395, 183317, '1', '4', 154859, 'IRE', 'Lost Signal', '2', '9-11', 62.1, 'NULL', '-', 5950, 'Alec Voikhansky', 223, 'R Hannon', NULL, NULL, NULL, 'Improved when dropped in trip, though still keen, and won a Salisbury maiden over 6f by 2 1/2l last time. Effective from 6-7f on fast ground and could progress again if settling better.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298396, 183317, '2', '2', 153799, 'IRE', 'Magnatura', '2', '9-7', 60.3, 'NULL', '-', 4172, 'Finley Marsh', 4154, 'T Ward', '1st', '85/40', 3.13, 'Benefited from debut experience to win a novice at Kempton by 3l last time. Returns from a short break and is effective over 7f on a sound surface.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298397, 183317, '3', '1', 153671, 'IRE', 'Must Be Ten', '2', '9-4', 58.95, 'NULL', '-', 5191, 'Saffie Osborne', 262, 'J A Osborne', NULL, NULL, NULL, 'Promising debut when runner-up in a Brighton maiden over 6f, beaten 4 1/2l after meeting early trouble. Off a short break since; should improve for the experience and may stay 7f.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298398, 183317, '4', '3', 155113, 'GB', 'Demetris Mouflon', '2', '8-9', 54.85, 'NULL', '-', 3860, 'Pierre-Louis Jamin', 162, 'B R Millman', NULL, NULL, NULL, 'Showed improvement from debut when beaten 8 1/4l in a Windsor novice over 6f last time. With the trainer in form, she looks one for nurseries.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298399, 183318, '1', '4', 111461, 'IRE', 'Chifa', '8', '9-9', 61.2, 'NULL', '65', 3959, 'William Cox', 1859, 'Ed De Giles', NULL, '18/1', 19.0, 'Never involved when down the field in a Haydock handicap most recently; effective at 7f on a sound surface. Below par of late but returns to last winning mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298400, 183318, '2', '5', 111073, 'GB', 'Flatley', '8', '9-8', 60.75, 'p', '64', 4172, 'Finley Marsh', 4151, 'A Wintle', '2nd', '11/2', 6.5, 'Ran to form when beaten 2l off 64 over 8f at Haydock last time; leading jockey returns to the saddle. Effective from 8-10f on a sound surface.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298401, 183318, '3', '1', 76056, 'GB', 'Harbour Vision', '10', '9-7', 60.3, 'b', '63', 2501, 'Joey Haynes', 2243, 'S Dixon', NULL, NULL, NULL, 'Went too hard early from a wide draw and finished down the field in a 9f Wolverhampton handicap most recently. Had been in good form prior and is consistent at 7-8f on a sound surface.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298402, 183318, '4', '9', 128757, 'GB', 'Cypriot Diaspora', '4', '9-7', 60.3, 'NULL', '63', 3797, 'Lewis Edmunds', 162, 'B R Millman', NULL, NULL, NULL, 'Ran to form when beaten 3 1/4l off 64 at Haydock last time. Effective from 6-7f and suited by cut; now dropped to a reasonable mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298403, 183318, '5', '8', 128086, 'GB', 'Mbappe', '4', '9-6', 59.85, 'NULL', '62', 5548, 'Joe Leavy', 4159, 'D M Loughnane', NULL, '10/1', 11.0, 'Weakened tamely and finished down the field in a Doncaster handicap most recently; generally out of form though stable is going well. Effective at 7f on a sound surface but struggling in 2025.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298404, 183318, '6', '2', 128242, 'IRE', 'Hows The Guvnor', '4', '9-5', 59.4, 'h', '61', 5329, 'Jonny Peate', 595, 'J Candlish', NULL, NULL, NULL, 'Extended poor run when beaten 9l in a Doncaster handicap last time; regressive profile.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298405, 183318, '7', '7', 130151, 'IRE', 'Charencey', '5', '9-3', 58.5, 'vt', '59', 5195, 'Callum Hutchinson', 45, 'Ian Williams', '1st', '9/2', 5.5, 'Poor run in first-time cheekpieces when down the field over 8f at Doncaster most recently. Generally out of form but tries a visor for the first time after a short break; effective at 7-8f.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298406, 183318, '8', '10', 100123, 'IRE', 'Windsor Pass', '7', '9-0', 57.15, 'NULL', '56', 22, 'L Morris', 2260, 'J Butler', NULL, NULL, NULL, 'Ran to form when second, beaten 5l in an 8f handicap at Southwell latest. Steadily progressive with a leading jockey back on board; consistent at 7-8f on a sound surface and capable off this mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298407, 183318, '9', '6', 97667, 'GB', 'The Cola Kid', '8', '8-7', 53.95, 'bt', '49', 5191, 'Saffie Osborne', 4229, 'G Harris', NULL, NULL, NULL, 'Short of room but flattened out when clear, beaten 3l off 51 over 6f here last time. Notable jockey booking; effective at 6-7f on a sound surface.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298408, 183319, '1', '7', 142234, 'USA', 'Kingsclere', '3', '9-9', 61.2, 'NULL', '55', 5329, 'Jonny Peate', 4240, 'J Ferguson', '1st', '16/5', 4.2, 'Keen and never involved on her final qualifying run when finishing down the field in a maiden at Haydock most recently. Possible improver in handicaps and likely to stay 1m.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298409, 183319, '2', '3', 140939, 'GB', 'On A Vespa', '3', '9-9', 61.2, 'p', '55', 5548, 'Joe Leavy', 224, 'J G Portman', NULL, NULL, NULL, 'Ran to form when stepping up in trip, beaten 3l off 55 over 8f at Windsor last time. Wears cheekpieces for the first time and effective between 7f and 8f on fast ground.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298410, 183319, '3', '6', 144378, 'GB', 'Step Along', '3', '9-8', 60.75, 'NULL', '54', 3797, 'Lewis Edmunds', 4160, 'W Muir & C Grassick', NULL, NULL, NULL, 'Ran to form when staying the longer trip, beaten 4l off 54 at Lingfield last time. Suited by a sound surface and effective from 5f to 7f.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298411, 183319, '4', '4', 141277, 'GB', 'Scenario', '3', '9-7', 60.3, 'p', '53', 3959, 'William Cox', 3791, 'Jack Jones', '2nd', '4/1', 5.0, 'Below form when back up in trip, beaten 10l in a classified race over 8f at Chepstow last time. Usually consistent, effective between 7f and 9f, but can be inconsistent.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298412, 183319, '5', '8', 142268, 'GB', 'Champagnebreakfast', '3', '9-7', 60.3, 'NULL', '53', 4077, 'Georgia Dobie', 4309, 'Edward Smyth-osbourne', NULL, '10/1', 11.0, 'Continued in poor form when beaten 8l in a novice at Wolverhampton last time. Trainer in form, but she returns from a long layoff and has yet to show anything of note.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298413, 183319, '6', '1', 138172, 'IRE', 'Dandy Khan', '3', '9-6', 59.85, 'NULL', '52', 5651, 'Taylor Fisher', 4168, 'P Gundry', NULL, NULL, NULL, 'No obvious excuse when finishing down the field in a handicap over 8f at Windsor most recently. Acts on any ground and effective between 7f and 8f, but currently out of form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298414, 183319, '7', '2', 138533, 'IRE', 'Oldbury Lad', '3', '9-0', 57.15, 'p', '46', 4172, 'Finley Marsh', 4229, 'G Harris', NULL, NULL, NULL, 'Poor run when dropped in grade, beaten 8 1/4l in a classified race over 6f at Lingfield last time. Generally out of form, though has a significant jockey booking, and effective over 6f on fast ground.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298415, 183319, '8', '9', 141734, 'IRE', 'Spinning Dancer', '3', '9-0', 57.15, 'NULL', '46', 22, 'L Morris', 111, 'J S Moore', NULL, NULL, NULL, 'Poor run when up in grade, beaten 8l in a handicap at Leicester last time. Generally out of form despite a significant jockey booking and looks on a stiff mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298416, 183319, '9', '5', 142176, 'GB', 'Havanas Dream', '3', '9-0', 57.15, 'p', '46', 5641, 'Elizabeth Gale', 172, 'R Harris', NULL, NULL, NULL, 'Has no worthwhile form and has yet to show anything over sprint trips.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298417, 183320, '1', '9', 129398, 'IRE', 'Aljezur', '4', '9-9', 61.2, 'p', '50', 3797, 'Lewis Edmunds', 595, 'J Candlish', '1st', '9/2', 5.5, 'Never threatened when stepped up in trip and finished down the field in a 9f handicap at Wolverhampton most recently. Usually held up and returns from a short break. Effective at 1m on a sound surface but remains an out-of-form maiden.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298418, 183320, '2', '7', 112428, 'IRE', 'Bobby Dassler', '6', '9-9', 61.2, 'h', '45', 5641, 'Elizabeth Gale', 326, 'Mrs A M Thorpe', NULL, NULL, NULL, 'Below form when fourth, beaten 7 1/4l, in an 8f handicap here last time and looked to need a longer trip. Effective at 1m on good to firm and good to soft. On a long losing run and no longer the force of old.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298419, 183320, '3', '4', 117090, 'GB', 'Fifty Sent', '6', '9-9', 61.2, 'p', '47', 5651, 'Taylor Fisher', 3420, 'T Faulkner', NULL, NULL, NULL, 'Made too much use of when beaten 3l in a classified race over 8f here last time. Acts on any ground and is well treated on best form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298420, 183320, '4', '11', 123897, 'GB', 'Olympic Quest', '5', '9-9', 61.2, 'p', '40', 22, 'L Morris', 3687, 'Joe Ponting', NULL, NULL, NULL, 'Awkward under pressure when beaten 7l in an 8f handicap at Bath last time. Better form shown on the all-weather and appears regressive.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298421, 183320, '5', '6', 145842, 'IRE', 'Rebel Cove', '4', '9-9', 61.2, 'p', '44', 6570, 'Taryn Langley', 2378, 'S Hodgson', NULL, NULL, NULL, 'Probably did too much too soon when well beaten in an 8f handicap at Bath most recently. Usually consistent, trainer in form, and effective from 8-10f on good or firm ground. Looks to have reached a level.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298422, 183320, '6', '5', 130669, 'IRE', 'Scarfo', '4', '9-9', 61.2, 'NULL', '40', 6944, 'Charlie Tucker', 528, 'B J Llewellyn', '2nd', '14/1', 15.0, 'Raced away from the main action early and was beaten 9 1/4l in an 8f handicap at Chepstow last time. Effective at 7-8f but currently in poor form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298423, 183320, '7', '3', 145126, 'IRE', 'Stoneacre', '5', '9-9', 61.2, 'p', '45', 2501, 'Joey Haynes', 2243, 'S Dixon', NULL, '22/1', 23.0, 'Needed the run when beaten 8l in an 8f handicap at Bath last time. Usually consistent, returns from a short break, and wears cheekpieces for the first time. Yet to show much and still unproven on turf.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298424, 183320, '8', '2', 122101, 'IRE', 'The Pug', '5', '9-9', 61.2, 'NULL', '49', 4172, 'Finley Marsh', 4151, 'A Wintle', NULL, NULL, NULL, 'Ran to form when third, beaten 3l, in an 11f handicap at Windsor last time. Effective from 10-11f on a sound surface and remains competitive off the current mark, but a long losing run is a concern.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298425, 183320, '9', '10', 154385, 'GB', 'Hampson Green', '3', '9-2', 58.05, 'NULL', '46', 5191, 'Saffie Osborne', 2301, 'D & C Kubler', NULL, NULL, NULL, 'Stopped quickly when stepped up in grade and finished down the field in a 7f novice at Leicester most recently. Yet to build on debut effort.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298426, 183320, '10', '8', 141539, 'FR', 'Pacific Man', '3', '9-2', 58.05, 'pt', '47', 3860, 'Pierre-Louis Jamin', 4133, 'O Greenall & J Guerriero', NULL, NULL, NULL, 'Ran to form when appreciating the longer trip, finishing fourth and beaten 3l in a handicap at Leicester last time. Effective at 9-10f on good ground, though his official mark looks stiff.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298427, 183320, '11', '1', 145320, 'IRE', 'Ta Craic Ann', '3', '9-2', 58.05, 'NULL', '50', 5548, 'Joe Leavy', 111, 'J S Moore', NULL, NULL, NULL, 'Outpaced and beaten early when down the field in a 12f handicap at Bath most recently. Yet to prove he has trained on.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298428, 183321, '1', '4', 133600, 'IRE', 'Moab', '5', '10-0', 63.5, 'NULL', '60', 5641, 'Elizabeth Gale', 562, 'Miss H C Knight', '2nd', '7/2', 4.5, 'Needed the run and was not knocked about after meeting trouble, beaten 6l in a handicap at Newbury last time. Had been in good form beforehand; effective from 10f to 12f on a sound surface, with a good mark on maiden and jumps form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298429, 183321, '2', '5', 102345, 'FR', 'Sea Of Charm', '7', '9-13', 63.0, 'b', '59', 3959, 'William Cox', 4158, 'G Nicholls', NULL, NULL, NULL, 'Back on her last winning mark, returned to form on quicker ground with a well-judged ride, landing a handicap by a neck off 55 over 11f at Windsor last time. Effective from 10f to 12f on a sound surface; generally consistent, though her revised mark will demand more.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298430, 183321, '4', '3', 153969, 'GB', 'Rogue Justice', '3', '9-4', 58.95, 'p', '59', 22, 'L Morris', 3791, 'Jack Jones', NULL, NULL, NULL, 'Improved but given too much to do when 12l third in a maiden over 10f at Yarmouth on his final qualifying run. Cheekpieces applied for the first time; usually held up; significant jockey booking. Effective at 10f on good to firm or good to soft and may get 12f; opening mark looks fair.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298431, 183321, '5', '2', 132832, 'IRE', 'Saachi', '4', '9-1', 57.6, 'v', '47', 5191, 'Saffie Osborne', 45, 'Ian Williams', '1st', '15/8', 2.88, 'Ran to current form but was outstayed late when stepped up in trip, beaten 1/2l off 47 at Leicester last time. Visor applied for the first time; significant jockey booking; off a short break. Acts on good, firm, and soft ground; an inconsistent maiden.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298432, 183321, '6', '6', 145757, 'IRE', 'Beaune', '3', '8-5', 53.05, 'NULL', '46', 5291, 'Jay Mackay', 528, 'B J Llewellyn', NULL, '15/2', 8.5, 'Had too much to do after blowing the start, beaten 3l in a classified race over 8f here last time. Usually consistent and suited by 10f; acts on good to soft. A consistent but exposed maiden.');
