INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298517, 183333, '6', '2', 138518, 'IRE', 'Dandy Magic', '3', '9-3', 58.5, 'NULL', '70', 931, 'P Mulrennan', 502, 'J S Goldie', NULL, NULL, NULL, 'Appeared not to stay when beaten by 7 1/2l in a handicap over 7f at Lingfield last time; top course jockey/trainer combination; usually held up; returning from a break; value selection based on balance of form');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298518, 183334, '1', '1', 130921, 'GB', 'South Shore', '4', '10-0', 63.5, 'h', '64', 1509, 'J P Sullivan', 679, 'Mrs R Carr', NULL, NULL, NULL, 'Slowly away when scoring by a neck off the mark of 60 over 6f at Wetherby in June; since came fifth and beaten by 3 1/4l off the mark of 64 last time out; runs off the same mark here; could figure');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298519, 183334, '2', '3', 124316, 'GB', 'Too Much', '5', '10-0', 63.5, 'h', '64', 5521, 'Kaiya Fraser', 922, 'D Thompson', NULL, NULL, NULL, "Ran to form when coming a 8 1/4l third in a handicap over 8f at Redcar on most recent run; does have better form on the AW; down 2lb's from last run; out of sorts at present and does have a bit to find");
