INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298558, 183338, '5', '5', 155788, 'IRE', 'Night Patrol', '2', '9-2', 58.05, 'NULL', '-', 1204, 'J P Fahy', 223, 'R Hannon', NULL, NULL, NULL, NULL);
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298559, 183338, '6', '1', 155943, 'IRE', 'St Anton', '2', '9-2', 58.05, 'NULL', '-', 928, 'S M Levey', 223, 'R Hannon', NULL, NULL, NULL, NULL);
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298560, 183339, '1', '3', 127953, 'GB', 'Angel Shared', '4', '9-12', 62.55, 'NULL', '84', 254, 'D C Costello', 2660, 'Steph Hollinshead', NULL, NULL, NULL, 'All out in finish involving four others landing a handicap by 1/2l off 81 here last time; enjoys making it; suited by 5/6f, acts on any; may have reached ceiling but very game');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298561, 183339, '2', '5', 141461, 'IRE', 'Raneenn', '3', '9-9', 61.2, 'h', '84', 4777, 'Cieren Fallon', 147, 'W J Haggas', '1st', '11/2', 6.5, 'Probably wanted further beaten 4l off 86 over 5f at Ascot last time; hood first time; trainer in form; effective 6/7f, acts on good to soft and good to firm; form has tailed off');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298562, 183339, '3', '6', 127344, 'GB', 'Miss Show Off', '4', '9-9', 61.2, 'NULL', '81', 7004, 'H Crouch', 230, 'C G Cox', NULL, NULL, NULL, 'Raced too freely beaten 6l in a handicap over 5f at Ascot last time; effective 5/6f on a sound surface; in and out of form');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298563, 183339, '4', '1', 141287, 'GB', 'Arabian Leopard', '3', '9-6', 59.85, 'NULL', '81', 208, 'J P Spencer', 244, 'D M Simcock', NULL, NULL, NULL, 'Ran to form beaten 3l off 81 at Goodwood last time; suited by 6/7f and a sound surface; in form');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298564, 183339, '5', '7', 141175, 'IRE', 'Greydreambeliever', '3', '9-6', 59.85, 'p', '81', 6871, 'Jack Nicholls', 2632, 'K R Burke', '2nd', '20/1', 21.0, 'Made plenty of use of but cheekpieces looked less effective second time down the field in a handicap at Goodwood most recent start; suited by 6f and a sound surface; temperament to prove');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298565, 183339, '6', '2', 145001, 'GB', 'Swiss Lightning', '3', '9-3', 58.5, 'p', '78', 5838, 'Billy Loughnane', 2414, 'J & T Gosden', NULL, NULL, NULL, 'Ran to best maiden form on handicap debut down in trip beaten 3/4l off 78 at Leicester last time; cheekpieces first time; significant jockey booking; suited by 6f, acts on a sound surface; workable mark');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298566, 183339, '7', '4', 145220, 'GB', 'Cuban Lady', '3', '9-1', 57.6, 'NULL', '76', 3287, 'K Shoemark', 3139, 'Tom Clover', NULL, NULL, NULL, "Didn't quite get home after racing too freely beaten 2l off 77 here last time; suited by 6f, acts on a sound surface; open to improvement if will settle better");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298567, 183340, '1', '4', 120623, 'IRE', 'Classic Speed', '5', '9-12', 62.55, 'NULL', '64', 928, 'S M Levey', 4096, 'Brian Toomey', NULL, NULL, NULL, 'Ran poorly, perhaps not handling fast ground comfortably held in a handicap over 9f at Epsom last time; suited by 1m on AW; yet to show much on turf and has lost form');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298568, 183340, '2', '1', 138432, 'GB', 'Calibos', '3', '9-9', 61.2, 'bt', '68', 101, 'Jim Crowley', 2301, 'D & C Kubler', NULL, '11/1', 12.0, 'Scored by 4l off 61 at Windsor penultimate start; race probably came too soon when well beaten off 67 last time; suited by 10f, acts on any; likely to return to form');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298569, 183340, '3', '6', 145774, 'IRE', 'Arundel', '3', '9-7', 60.3, 'v', '66', 7004, 'H Crouch', 295, 'E A L Dunlop', '1st', '15/8', 2.88, 'Scored by 2l off 58 at Pontefract in May; visored and suited by step-up in trip when second beaten 1/2l off 65 last time; effective 10f, 12f suits, acts on good to soft and good to firm; staying type, open to improvement');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298570, 183340, '4', '3', 147996, 'GB', 'Huggable', '3', '9-7', 60.3, 'NULL', '66', 4769, 'Morgan Cole', 3782, 'Dylan Cunha', '2nd', '2/1', 3.0, 'Well handicapped on novice form, step-up in trip suited landing a handicap by 6l off 60 at Epsom last time; suited by 10f and a sound surface; quirky but remains well treated at weights');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298571, 183340, '5', '5', 145057, 'IRE', 'Betty Bassett', '3', '9-4', 58.95, 'p', '63', 5838, 'Billy Loughnane', 45, 'Ian Williams', NULL, NULL, NULL, 'Yard won this last year; scored by a head off 62 at Wetherby in June; ridden to stay and debatable whether really saw it out fifth beaten 3 1/4l off 64 last time; suited by 10f and a sound surface; fraction below best of late');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298572, 183340, '6', '2', 138994, 'IRE', 'Gretna Dreams', '3', '9-2', 58.05, 'NULL', '61', 618, 'P Cosgrave', 282, 'S C Williams', NULL, NULL, NULL, 'Back to best ridden near pace on a sharp track landing a handicap by 2 1/2l off 56 at Brighton last time; suited by easy 10f and sound surface; needs the right conditions');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298573, 183341, '1', '1', 144380, 'IRE', 'Venezuelan', '3', '9-9', 61.2, 'b', '81', 7004, 'H Crouch', 152, 'R M Beckett', '1st', '4/9', 1.44, 'Well backed, making running suited though race fell apart when winning a maiden at Lingfield by 13l last time; suited by 12f and a sound surface; looks irresolute and untrustworthy');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298574, 183341, '2', '3', 145404, 'IRE', 'Atlantic Sunset', '3', '9-5', 59.4, 'v', '77', 24, 'N Callan', 4122, 'C Johnston', NULL, NULL, NULL, "Scored by a length off 74 here penultimate start; raced lazily beaten 12l off 78 last time; suited by 12f and a sound surface; yard's out of form runners usually bounce back");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298575, 183341, '3', '2', 141475, 'IRE', 'Bondi', '3', '9-1', 57.6, 'NULL', '73', 928, 'S M Levey', 223, 'R Hannon', '2nd', '5/1', 6.0, 'Scored by 3/4l off 68 over 11f at Windsor penultimate start; disappointing up 5lb beaten 13l off 73 last time; suited by 12f and fast ground; had been progressive');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298576, 183342, '1', '2', 135665, 'GB', 'Mount Atlas', '4', '10-0', 63.5, 'NULL', '107', 3005, 'Oisin Murphy', 256, 'A M Balding', NULL, NULL, NULL, 'Smart sort who was back to winning ways at Ascot last time; acts on any but particularly effective on fast; 5lb rise for last time means more is needed to follow up here.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298577, 183342, '2', '4', 127045, 'IRE', 'Naqeeb', '5', '9-12', 62.55, 'NULL', '105', 5205, 'Ryan Sexton', 744, 'Miss J A Camacho', '1st', '7/1', 8.0, 'On a losing run of 12 but some good efforts in top 10-12f handicaps lately, including latest second over 10f at Goodwood last time; leading player.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298578, 183342, '3', '6', 120874, 'USA', 'This Songisforyou', '7', '9-6', 59.85, 'NULL', '99', 3574, 'Tom Marquand', 4245, 'E Mullins', NULL, NULL, NULL, "Ran okay on the figures when fifth of six in a 12f Gr 3 last time; interesting on last September's 10f win at the Curragh and is shrewd trainer's only runner here over the four days.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298579, 183342, '4', '8', 128732, 'GB', 'Insanity', '5', '9-4', 58.95, 'NULL', '97', 4174, 'Rossa Ryan', 57, 'A King', '2nd', '8/1', 9.0, 'Down the field in this last year but may well fare better this time, with such as his win at Ayr three starts back and latest sound third at Ascot entitling him to be thereabouts.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298580, 183342, '5', '9', 132329, 'IRE', 'French Duke', '4', '9-4', 58.95, 'h', '97', 1245, 'James Doyle', 2048, 'R Varian', NULL, NULL, NULL, 'Yard won this last year; slowly away when bit disappointing over 1m6f at Goodwood most recent run; return to 12f may help but needs to rediscover his good 2024 form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298581, 183342, '6', '10', 133225, 'GB', 'Champagne Prince', '4', '9-2', 58.05, 'NULL', '95', 4468, 'D Egan', 274, 'Jane Chapple-Hyam', NULL, NULL, NULL, 'Well below-par at Newmarket most recently, since when he has been gelded; better on the AW and looks on a high enough mark on balance of his turf form; others preferred.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298582, 183342, '7', '1', 119903, 'IRE', 'Chillingham', '6', '9-1', 57.6, 'v', '94', 3300, 'Hollie Doyle', 4275, 'E Bethell', NULL, '12/1', 13.0, "Interesting off this mark on the pick of his form and though below-par here latest, that was a muddling event; awarded the race in the stewards' room here in June; worth considering.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298583, 183342, '8', '7', 124651, 'IRE', 'Zanndabad', '6', '8-13', 56.65, 'NULL', '92', 1055, 'W Buick', 366, 'A J Martin', NULL, '9/1', 10.0, 'Hinted that all of his Flat ability remains when set a lot to do in the Northumberland Plate (2m, AW) last time in June; ran well hurdling latest; longer trip would suit better; each-way chance.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298584, 183342, '9', '3', 118507, 'IRE', 'Asgards Captain', '5', '8-9', 54.85, 'NULL', '88', 1130, 'J F Egan', 3782, 'Dylan Cunha', NULL, NULL, NULL, 'Bit up and down lately but did run to form at Ascot last time and, with trip/ground fine, has each-way chance.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298585, 183342, '10', '11', 113265, 'GB', 'Marhaba The Champ', '6', '8-9', 54.85, 'NULL', '88', 1922, 'Jason Hart', 467, 'Mrs S Leech', NULL, NULL, NULL, "Won this in 2023 and though not so good nowadays, latest second at Doncaster (10f) was best run for a long while; sold out of Kevin Ryan's yard for 8,000gns since; considered.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298586, 183342, '11', '5', 110878, 'IRE', 'Austrian Theory', '6', '8-4', 52.6, 'NULL', '83', 896, 'D Fentiman', 470, 'T D Easterby', NULL, NULL, NULL, 'Interesting on his sound fifth in top 10.3f handicap here last month but less good twice since and bit to prove overall; stamina beyond 10.3f is unproven.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298587, 183343, '1', '4', 105203, 'IRE', 'Trawlerman', '7', '9-8', 60.75, 'h', '121', 1055, 'W Buick', 2414, 'J & T Gosden', '1st', '8/11', 1.73, 'Top-class stayer who ran them ragged in the Gold Cup (2m4f) at Ascot last time; fully effective at 2m while he won only previous start here (2022 Ebor); should be very hard to pass.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298588, 183343, '2', '6', 105752, 'GB', 'Al Nayyir', '7', '9-5', 59.4, 'p', '111', 1245, 'James Doyle', 3139, 'Tom Clover', NULL, NULL, NULL, 'Only just edged out in this last year but not quite so good this season, including well-held third to Trawlerman at Sandown in May; others preferred.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298589, 183343, '3', '5', 115054, 'IRE', 'Al Qareem', '6', '9-5', 59.4, 'NULL', '114', 3348, 'C Lee', 2632, 'K R Burke', NULL, NULL, NULL, "Admirably reliable front-running 6yo who comes here in fine form after two recent 14f wins here; stays 15f on soft and 2m shouldn't be an issue; more needed against the top two here.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298590, 183343, '4', '3', 93101, 'GB', 'Dubai Future', '9', '9-5', 59.4, 'hp', '114', 5007, 'K Stott', 1397, 'S bin Suroor', NULL, NULL, NULL, 'Similar level to Gold Cup form when running very respectably in Goodwood Cup last time; stays 2m, acts on a sound surface; work to do to trouble the top two here.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298591, 183343, '5', '1', 121896, 'IRE', 'Sweet William', '6', '9-5', 59.4, 'v', '115', 193, 'R Havlin', 2414, 'J & T Gosden', NULL, NULL, NULL, 'Very consistent and high-class 6yo who found 2m4f too far in Ascot Gold Cup but was back to form when third in Goodwood Cup last time; the clear main danger to Trawlerman.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298592, 183343, '6', '2', 77631, 'IRE', 'Shackleton', '3', '8-8', 54.4, 'p', '107', 817, 'W M Lordan', 1283, "A P O'Brien", '2nd', '15/2', 8.5, "Smart 3yo though form doesn't compare to the two top-rated here; step up to 2m may well suit; ran to best when second in 14f Gr 2 latest; cheekpieces first time; vulnerable, all told.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298593, 183344, '1', '4', 153054, 'IRE', 'Comical Point', '2', '9-2', 58.05, 'NULL', '95', 3005, 'Oisin Murphy', 256, 'A M Balding', NULL, NULL, NULL, "Yard won this last year; raced far too freely in Gr 2 at Newmarket last time; in good form prior and still isn't fully exposed, so well worth considering for top trainer-jockey combo.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298594, 183344, '2', '1', 153103, 'IRE', 'Do Or Do Not', '2', '9-2', 58.05, 'p', '105', 3574, 'Tom Marquand', 891, 'E Walker', NULL, NULL, NULL, 'Still a maiden but sets the standard on placed runs in three Gr 2s, last time upped to 7f at Goodwood; cheekpieces first time; not sure this flat 6f will be ideal but strong form claims.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298595, 183344, '3', '5', 153525, 'GB', 'Egoli', '2', '9-2', 58.05, 'NULL', '93', 4174, 'Rossa Ryan', 152, 'R M Beckett', '1st', '4/1', 5.0, "Raced on 'wrong' part of course in Gr 2 at Goodwood last time and readily excused that; in good form prior to that; suited by 6f, acts on good and fast; needs more but isn't fully exposed.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298596, 183344, '4', '8', 152606, 'IRE', 'Irish Fighter', '2', '9-2', 58.05, 'NULL', '87', 2068, 'M Barzalona', 2377, 'I Mohammed', NULL, NULL, NULL, 'Creditable fifth in the Super Sprint at Newbury last time; has raced only at 5f; something to find up in grade.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298597, 183344, '5', '6', 155243, 'IRE', 'Lifeplan', '2', '9-2', 58.05, 'NULL', '-', 4356, 'Zak Wheatley', 148, 'D Carroll', NULL, '5/1', 6.0, 'A length winner in a 6f novice at Thirsk on debut, when backed beforehand; this is quite a bit harder but that debut win was very promising.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298598, 183344, '6', '3', 153844, 'GB', 'Reciprocated', '2', '9-2', 58.05, 'NULL', '99', 3348, 'C Lee', 2632, 'K R Burke', '2nd', '9/2', 5.5, "450,000gns yearling; too free and highly likely didn't stay in Listed race over 7f at Ascot last time; highly promising in two 6f wins before that; very much a contender back at 6f again now.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298599, 183344, '7', '7', 153560, 'IRE', 'Rock On Thunder', '2', '9-2', 58.05, 'NULL', '95', 5007, 'K Stott', 28, 'K A Ryan', NULL, NULL, NULL, '380,000gns yearling; ran to form when 4l second to a smart winner in 6f Listed race at Newbury latest; bit more probably needed.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298600, 183344, '8', '2', 154567, 'IRE', 'Yorkshire Puds', '2', '9-2', 58.05, 'NULL', '-', 1922, 'Jason Hart', 1668, 'M Appleby', NULL, NULL, NULL, 'Twice-raced maiden; down the field in a maiden at Goodwood most recently; difficult to fancy at this level.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298601, 183345, '1', '13', 118113, 'IRE', 'Jm Jungle', '5', '10-1', 63.95, 'NULL', '112', 1922, 'Jason Hart', 4110, 'J & S Quinn', NULL, NULL, NULL, 'In form but improved markedly to win Gr 2 at Goodwood last time; suited by 5f, acts on any; thoroughly admirable sort who has place claims if he can confirm that latest improvement.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298602, 183345, '2', '12', 122242, 'IRE', 'Kerdos', '5', '10-1', 63.95, 'NULL', '106', 4174, 'Rossa Ryan', 230, 'C G Cox', NULL, '33/1', 34.0, "Smart sort who probably raced on the 'wrong' side at Goodwood last time; acts on any ground; up and down in recent times and bit to prove overall; cheekpieces worn latest are left off.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298603, 183345, '3', '1', 110495, 'GB', 'Manaccan', '6', '10-1', 63.95, 't', '99', 3348, 'C Lee', 324, 'J Ryan', NULL, '100/1', 101.0, 'Gradually refinding his form since back from two years off, last time fourth in Ascot handicap; even the best of his old form would need improving upon; others preferred.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298604, 183345, '4', '8', 133673, 'IRE', 'Night Raider', '4', '10-1', 63.95, 'NULL', '105', 1245, 'James Doyle', 2632, 'K R Burke', NULL, NULL, NULL, "Best form so far on AW but has never had the chance to run on a fast, flat 5f on quick turf, conditions he'll finally have here; has speed to burn and very bold show wouldn't surprise.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298605, 183345, '5', '14', 118027, 'GB', 'Rumstar', '5', '10-1', 63.95, 'NULL', '113', 3023, 'Rob Hornby', 224, 'J G Portman', NULL, '20/1', 21.0, 'Bit below best at The Curragh last time; suited by 5f, acts on any, likes it fast; best form, such as when showing late burst in two 2025 Gr 3 wins, makes him a contender.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298606, 183345, '6', '15', 121913, 'IRE', 'Spartan Arrow', '5', '10-1', 63.95, 'p', '106', 3300, 'Hollie Doyle', 4143, 'A Watson', NULL, NULL, NULL, 'Yard won this last year; well held up in class in Gr 2 at Goodwood last time; suited by an easy 5f and a sound surface; smart sort but this demands a career-best.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298607, 183345, '7', '17', 119596, 'GB', 'Washington Heights', '5', '10-1', 63.95, 'NULL', '107', 9, 'T Eaves', 28, 'K A Ryan', NULL, NULL, NULL, 'Very respectable sixth in this last year; form of latest C&D Listed-race win is working out well and each-way claims on that.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298608, 183345, '8', '3', 137676, 'IRE', 'Aint Nobody', '3', '9-13', 63.0, 'p', '99', 5007, 'K Stott', 28, 'K A Ryan', NULL, NULL, NULL, 'Plenty to find on balance of form, last time down the field in Listed race over 6f at Chester last time; cheekpieces first time; return to 5f may help but too much to find to appeal much.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298609, 183345, '9', '9', 135087, 'GB', 'Arizona Blaze', '3', '9-13', 63.0, 'NULL', '113', 4468, 'D Egan', 1137, 'A Murray', NULL, NULL, NULL, 'Dependable colt who comes here in great form at 5-6f, last time winning well in 5f Gr 2 at The Curragh; that followed an excellent in 6f Gr 1 at Ascot; leading contender.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298610, 183345, '10', '5', 137148, 'AUS', 'Asfoora', '7', '9-12', 62.55, 'b', '114', 3005, 'Oisin Murphy', 4361, 'Henry Dwyer', '1st', '7/1', 8.0, 'Ran to current form and still below best at Goodwood last time but ground there slower than ideal; sound fourth in this last year but even better form earlier in 2024; needs to refind that.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298611, 183345, '11', '6', 132183, 'USA', 'Frost At Dawn', '4', '9-12', 62.55, 'v', '109', 2068, 'M Barzalona', 493, 'W J Knight', NULL, NULL, NULL, 'Ground was a bit slower than ideal when running well in Gr 2 at Goodwood latest; previous second of 20 in Ascot Gr 1 makes her an each-way player and trip/ground here are ideal.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298612, 183345, '12', '7', 153425, 'GB', 'Mgheera', '5', '9-12', 62.55, 'NULL', '108', 1055, 'W Buick', 891, 'E Walker', '2nd', '11/1', 12.0, "Ran okay in second at The Curragh latest when tardy start didn't help; fast ground an unknown but form of her Gr 2 win at Haydock in May is good and is well worth considering.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298613, 183345, '13', '11', 129308, 'IRE', 'Shes Quality', '4', '9-12', 62.55, 'b', '108', 5450, 'J J G Ryan', 4237, 'J Davison', NULL, NULL, NULL, 'Four very good runs in second place this season, last time in Gr 2 at Goodwood; the emphasis on out-and-out speed in this particular race is a plus and well worth considering.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298614, 183345, '14', '16', 137158, 'GB', 'Celandine', '3', '9-10', 61.65, 'NULL', '105', 3574, 'Tom Marquand', 891, 'E Walker', NULL, '33/1', 34.0, "Won Gr 2 Lowther (6f) here last year; bit below-par latest but previous reappearance third here (6f) showed she'd trained on; seemed to find 5f too sharp once last season.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298615, 183345, '15', '2', 142159, 'IRE', 'Sayidah Dariyan', '3', '9-10', 61.65, 'NULL', '110', 930, 'R L Moore', 4207, 'R Hughes', NULL, NULL, NULL, 'Travelled very well and then quickened when winning Gr 3 here over 6f last time; steadily progressive and may well be able to bridge the gap to Gr 1 level; probably pacey enough for 5f.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298616, 183345, '16', '4', 148032, 'IRE', 'Lady Iman', '2', '8-2', 51.7, 'NULL', '106', 18, 'J Fanning', 1081, 'G M Lyons', NULL, NULL, NULL, 'Only defeat in five runs came when outstayed over 6f; decisive win in 5f Gr 3 at Goodwood last time; suited by 5f and a sound surface; 2yos can win this race and much respected.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298617, 183345, '17', '10', 152685, 'GB', 'Spicy Marg', '2', '8-2', 51.7, 'NULL', '94', 239, 'Harry Bentley', 318, 'M L W Bell', NULL, NULL, NULL, 'Back on track with decisive win in useful race at Goodwood last time; trip/ground look ideal but the other 2yo here, Lady Iman, has superior form so this filly needs to improve.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298618, 183346, '1', '8', 137023, 'IRE', 'Akecheta', '5', '9-12', 62.55, 'NULL', '90', 1802, 'S A Gray', 3311, 'Kevin Coleman', '2nd', '13/2', 7.5, 'Unraced on faster than good; mostly creditable runs recently, last time finishing well from off the pace for fourth at Goodwood; this is arguably less competitive and leading claims.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298619, 183346, '2', '10', 129948, 'GB', 'Ciara Pearl', '5', '9-11', 62.1, 'p', '89', 2068, 'M Barzalona', 2301, 'D & C Kubler', NULL, NULL, NULL, 'Bit below-par over 12f at Ascot last time; stays that trip but 10f is probably her optimum; bit more needed on balance of recent form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298620, 183346, '3', '9', 136773, 'GB', 'Power Of Destiny', '4', '9-9', 61.2, 'NULL', '87', 4174, 'Rossa Ryan', 152, 'R M Beckett', NULL, NULL, NULL, 'Trip/ground are fine and definite claims on best form but she will need to step up on recent below-par efforts, last time at Goodwood.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298621, 183346, '4', '3', 122436, 'GB', 'Roarin Success', '5', '9-7', 60.3, 'NULL', '85', 1055, 'W Buick', 4104, 'Harry Charlton', NULL, NULL, NULL, 'Game when winning at Hamilton on penultimate start and ran well again when front-running second at Doncaster last time; bit more needed in this better-contested race.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298622, 183346, '5', '13', 145005, 'IRE', 'Zgharta', '3', '9-4', 58.95, 'h', '89', 3005, 'Oisin Murphy', 256, 'A M Balding', '1st', '5/2', 3.5, "Didn't get a clear run when catching the eye at Goodwood (1m) last time; 10f winner earlier this season; much respected for leading trainer-jockey combination.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298623, 183346, '6', '5', 126897, 'IRE', 'Fiver Friday', '5', '9-3', 58.5, 'NULL', '81', 1026, 'D Allan', 3475, 'Paul Traynor', NULL, NULL, NULL, 'Well beaten in a handicap hurdle at Sligo latest; in better form on the Flat before that but more needed even on those efforts; fast ground would be a concern.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298624, 183346, '7', '11', 144764, 'GB', 'Wonder Star', '3', '8-13', 56.65, 'NULL', '84', 3574, 'Tom Marquand', 147, 'W J Haggas', NULL, NULL, NULL, 'Lightly-raced filly who was good second in competitive race at Goodwood last time on handicap debut; big chance on that up 2lb and ought to still be open to improvement.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298625, 183346, '8', '12', 121376, 'GB', 'Bint Al Daar', '5', '8-13', 56.65, 'pt', '77', 6941, 'Alfie Gee', 4239, 'K Frost', NULL, NULL, NULL, "Hasn't been firing at all in recent runs and risky proposition at present; however, she's 8lb lower than when second in this last year and not ruled out in cheekpieces for the first time.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298626, 183346, '9', '1', 132221, 'IRE', 'Jujubella', '4', '8-11', 55.75, 'p', '75', 1013, 'P J McDonald', 4486, 'Lucinda & Scud', NULL, '40/1', 41.0, 'Scored at Haydock on penultimate start; that was at a shade further but this trip is fine too; bit to find on balance up in grade.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298627, 183346, '10', '4', 153348, 'GB', 'Brielle', '3', '8-11', 55.75, 'NULL', '82', 29, 'David Probert', 1642, "D O'Meara", NULL, '12/1', 13.0, "Fulfilled previous 8-12f promise when improving to win 1m novice at Hamilton latest; by stamina influence sire, so that augurs well for 10.3f; more needed but she's a potential improver.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298628, 183346, '11', '2', 145409, 'GB', 'Cape Flora', '3', '8-8', 54.4, 'NULL', '79', 1067, "K T O'Neill", 2414, 'J & T Gosden', NULL, NULL, NULL, "Much-improved when winning at Leicester (10f) last time; up 11lb in better grade race but she's very well-bred and hails from a top yard, so could easily be up to it.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298629, 183346, '12', '7', 142368, 'IRE', 'Callisto Dream', '3', '8-8', 54.4, 'NULL', '79', 2892, 'Connor Beasley', 4275, 'E Bethell', NULL, NULL, NULL, "Lightly raced so it's possible she can find the bit more needed; however, pedigree raises stamina question upped in trip and others are preferred.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298630, 183346, '13', '6', 141119, 'IRE', 'Blessed Star', '3', '8-6', 53.5, 'NULL', '77', 239, 'Harry Bentley', 4122, 'C Johnston', NULL, NULL, NULL, 'Consistent maiden at up to 1m, last time creditable third in Goodwood handicap; elements of pedigree are encouraging as regards 10.3f; worth considering.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298631, 183347, '1', '10', 155267, 'GB', 'Beny Nahar', '2', '9-7', 60.3, 'NULL', '-', 1055, 'W Buick', 4122, 'C Johnston', NULL, NULL, NULL, 'Similar level of form in two second places, last time in a novice at Haydock (7f; led, bit keen there); one of the likelier form contenders and has to be respected.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298632, 183347, '2', '12', 154936, 'GB', 'Bond', '2', '9-7', 60.3, 'NULL', '-', 1013, 'P J McDonald', 2338, 'P Twomey', NULL, '12/1', 13.0, 'Well held fifth in a maiden over 8f at Killarney on debut; only 4-1 there so better was evidently expected; others appeal more.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298633, 183347, '3', '9', 155924, 'IRE', 'Ephron', '2', '9-7', 60.3, 'NULL', '-', 2892, 'Connor Beasley', 4201, 'G Tutty', NULL, '20/1', 21.0, '24 March foal; 52,000euros breeze-up purchase by Calyx; dam useful at 10f; likely best watched.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298634, 183347, '4', '4', 154700, 'GB', 'Explosive Finnish', '2', '9-7', 60.3, 'NULL', '-', 3930, 'Ben Sanderson', 4239, 'K Frost', NULL, NULL, NULL, 'Just a modicum of promise in a novice over 5f at Nottingham on debut; highly likely best watched.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298635, 183347, '5', '7', 151956, 'IRE', 'Frescobaldi', '2', '9-7', 60.3, 'NULL', '-', 930, 'R L Moore', 1283, "A P O'Brien", '1st', '4/1', 5.0, 'Benefited from debut experience when close second in a maiden at Fairyhouse (7f) latest, going clear but nabbed late on; top yard won this in 2023; leading player.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298636, 183347, '6', '5', 155927, 'IRE', 'Ice Cube', '2', '9-7', 60.3, 'NULL', '-', 3755, 'George Wood', 4241, 'R Spencer', NULL, NULL, NULL, '19 February foal; 50,000gns Phoenix Of Spain colt; dam very useful at 8f; likely best watched.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298637, 183347, '7', '11', 155928, 'IRE', 'Inishbeg', '2', '9-7', 60.3, 'NULL', '-', 5007, 'K Stott', 28, 'K A Ryan', '2nd', '7/1', 8.0, '8 February foal; 500,000gns Ghaiyyath colt; half-brother to Volterra, very smart at 7f; dam useful at 6f; interesting on paper and warrants a market check for sure.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298638, 183347, '8', '15', 155278, 'GB', 'King Of Thunder', '2', '9-7', 60.3, 'NULL', '-', 29, 'David Probert', 4161, 'H Palmer', NULL, NULL, NULL, 'Some promise when 5l fourth in a maiden over 6f at Ascot on debut but this definitely demands more.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298639, 183347, '9', '2', 153426, 'GB', 'Naval Light', '2', '9-7', 60.3, 'NULL', '87', 1245, 'James Doyle', 2632, 'K R Burke', NULL, NULL, NULL, "360,000gns 2yo; plenty of ability in three runs at 5-6f, last time second at Goodwood latest; shapes as though he'll stay 7f; sets the standard on form and leading contender.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298640, 183347, '10', '8', 154098, 'IRE', 'New Monarch', '2', '9-7', 60.3, 'NULL', '-', 3005, 'Oisin Murphy', 256, 'A M Balding', NULL, NULL, NULL, 'Second in both starts, at Newbury and then Ascot (led), both at 6f; pedigree suggests 7f should suit; bit more needed for his leading trainer-jockey combination.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298641, 183347, '11', '14', 155935, 'GB', 'Night Wolf', '2', '9-7', 60.3, 'NULL', '-', 1922, 'Jason Hart', 4110, 'J & S Quinn', NULL, NULL, NULL, '17 February foal; 160,000gns Kodi Bear colt; half-brother to Galen, high-class at 10f; dam smart from 5f to 6f; probably best watched on debut.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298642, 183347, '12', '1', 155255, 'IRE', 'Red Spells Danger', '2', '9-7', 60.3, 'NULL', '-', 1026, 'D Allan', 470, 'T D Easterby', NULL, NULL, NULL, 'Promising debut third in a C&D novice last month; that form is reasonable and though more is needed here, not ruled out.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298643, 183347, '13', '3', 155354, 'FR', 'Sea The Power', '2', '9-7', 60.3, 'NULL', '-', 5035, 'O McSweeney', 4129, 'A Keatley', NULL, NULL, NULL, 'Raced freely when quite promising debut third third in a novice at Beverley debut; plenty more needed here, though.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298644, 183347, '14', '6', 155942, 'GB', 'Spyce', '2', '9-7', 60.3, 'NULL', '-', 4174, 'Rossa Ryan', 57, 'A King', NULL, '18/1', 19.0, '8 March foal; 280,000gns breeze-up purchase by Too Darn Hot; half-brother to Accentuate, very useful at 8f; dam very useful at 8f; worth a precautionary market check.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298645, 183347, '15', '13', 154668, 'GB', 'Isle of Fernandez', '2', '9-2', 58.05, 'NULL', '-', 9, 'T Eaves', 28, 'K A Ryan', NULL, NULL, NULL, "Had benefited from debut experience when second in a 7f fillies' maiden at Goodwood latest; more needed against colts this time.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298646, 183348, '1', '15', 147215, 'IRE', 'Fearnot', '3', '9-9', 61.2, 'h', '104', 29, 'David Probert', 230, 'C G Cox', '2nd', '6/1', 7.0, 'Most progressive and came on again when winning good handicap at Ascot last time; unraced as a 2yo and may continue progressing; 5lb rise is fair; leading player.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298647, 183348, '2', '16', 136748, 'GB', 'Dividend', '3', '9-4', 58.95, 'NULL', '99', 4174, 'Rossa Ryan', 4202, 'Dr R Newland & J Insole', NULL, '18/1', 19.0, 'Progressive colt who ran very well when fourth of 30 in top handicap at Ascot last time back in June; off a short break now; bit more needed up 4lb but could come on again.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298648, 183348, '3', '10', 152814, 'FR', 'Supido', '3', '9-4', 58.95, 'p', '99', 1922, 'Jason Hart', 45, 'Ian Williams', NULL, '22/1', 23.0, 'Creditable runs in two very good 1m Ascot handicaps lately (better run in the first of them); cheekpieces first time; looks more exposed than some and may be vulnerable win-wise.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298649, 183348, '4', '9', 151973, 'GB', 'Montpellier', '3', '9-4', 58.95, 'NULL', '99', 930, 'R L Moore', 4240, 'J Ferguson', '1st', '4/1', 5.0, 'Lightly-raced and gradually progressive 3yo who ran well when running-on fourth at Goodwood (7f) last time; very much a contender upped to 1m now.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298650, 183348, '5', '4', 136793, 'GB', 'Yah Mo Be There', '3', '9-3', 58.5, 'NULL', '98', 4468, 'D Egan', 4241, 'R Spencer', NULL, NULL, NULL, 'Shaped as though a return to 1m might well suit when running-on fifth over 7f in decent handicap at Goodwood last time; met some trouble there too; feasible mark; interesting runner.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298651, 183348, '6', '13', 137936, 'IRE', 'Tiger Mask', '3', '9-2', 58.05, 'p', '97', 3348, 'C Lee', 2632, 'K R Burke', NULL, NULL, NULL, "Useful 2yo but didn't show enough on belated seasonal debut on Newcastle AW in June to make much appeal for now; cheekpieces first time; upped to 1m now.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298652, 183348, '7', '5', 141448, 'IRE', 'Fifth Column', '3', '9-2', 58.05, 'p', '97', 1055, 'W Buick', 2414, 'J & T Gosden', NULL, NULL, NULL, 'Game when scoring at Newmarket (1m) on penultimate start before running well enough at Goodwood (when soft was possibly not ideal); top trainer-jockey combo; shortlisted.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298653, 183348, '8', '6', 145396, 'IRE', 'Teroomm', '3', '8-13', 56.65, 'NULL', '94', 3005, 'Oisin Murphy', 2048, 'R Varian', NULL, '10/1', 11.0, 'Too free last time and needs to settle better; Oisin Murphy taking over may well help and this colt has definite claims on the form of his good win at Haydock three starts back in May.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298654, 183348, '9', '8', 153480, 'IRE', 'Big Leader', '3', '8-13', 56.65, 'NULL', '94', 1013, 'P J McDonald', 317, 'G R Oldroyd', NULL, NULL, NULL, 'Made it three from three with narrow success on handicap debut at Thirsk last time; up 3lb in a better-contested race but he ought to be open to further progress.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298655, 183348, '10', '11', 142717, 'IRE', 'Sea Force', '3', '8-8', 54.4, 'NULL', '89', 3574, 'Tom Marquand', 147, 'W J Haggas', NULL, NULL, NULL, 'Yard won this last year; creditable series of runs continued at Goodwood last time; first-time cheekpieces worn there are left off; worth considering.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298656, 183348, '11', '2', 141138, 'IRE', 'King Casper', '3', '8-7', 53.95, 'NULL', '88', 3030, 'Joanna Mason', 4161, 'H Palmer', NULL, NULL, NULL, 'Down the field in a handicap at Goodwood most recent, though ground there was possibly unsuitable; others are more progressive and appeal more.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298657, 183348, '12', '17', 140822, 'IRE', 'We Dare To Dream', '3', '8-7', 53.95, 'NULL', '88', 239, 'Harry Bentley', 1642, "D O'Meara", NULL, NULL, NULL, "Mostly creditable runs this season before below-par run at Goodwood latest (ground not as testing as 'heavy' description suggests and should have done better); opposable now.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298658, 183348, '13', '12', 139156, 'GB', 'Impartiality', '3', '8-6', 53.5, 'p', '87', 2892, 'Connor Beasley', 3406, 'Phillip Makin', NULL, '18/1', 19.0, 'Remains gradually progressive, last time showing career-best form when second at Goodwood; ground any faster than good an unknown but much respected otherwise.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298659, 183348, '14', '1', 138284, 'GB', 'Sir Paul Ramsey', '3', '8-6', 53.5, 'NULL', '87', 18, 'J Fanning', 4122, 'C Johnston', NULL, NULL, NULL, 'Career-best form with narrow success at Haydock last time; may be open to further progress at 1m so not ruled out despite being 5lb higher in better grade than last time.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298660, 183348, '15', '3', 140945, 'IRE', 'Point Of Contact', '3', '8-6', 53.5, 'NULL', '87', 1067, "K T O'Neill", 256, 'A M Balding', NULL, NULL, NULL, "Didn't get a clear run when running creditably at Goodwood last time; this lightly-raced colt hails from a leading yard and is very much an each-way contender.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298661, 183348, '16', '14', 146753, 'IRE', 'Miami Matrix', '3', '8-5', 53.05, 'p', '86', 5307, 'Aiden Brookes', 4161, 'H Palmer', NULL, NULL, NULL, 'Progressive vein of form came to an end with down-the-field effort at Goodwood last time; cheekpieces first time; bit to find overall and others are preferred.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298662, 183348, '17', '7', 139084, 'IRE', 'Knights Gold', '3', '8-2', 51.7, 'h', '83', 3300, 'Hollie Doyle', 4202, 'Dr R Newland & J Insole', NULL, NULL, NULL, "Having a fine season and though thwarted in his bid for a fifth win of 2025 last time, that close third (hampered) at Goodwood means he's very much an each-way contender at least here.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298663, 183349, '1', NULL, 112012, 'IRE', 'Dynamic Force', '6', '11-12', 75.25, 'NULL', '-', 4274, "D J O'Keeffe", 352, 'T G McCourt', NULL, NULL, NULL, 'Forced wide from a poor draw and beaten 3 1/4l in a 7f handicap at Naas last time. Generally out of form; effective on fast ground up to 1m on the flat, but stamina remains to be proven over hurdles.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298664, 183349, '2', NULL, 121392, 'IRE', 'Matt Connor', '5', '11-12', 75.25, 'h', '-', 2946, 'D Meyler', 953, 'J P Dempsey', NULL, NULL, NULL, 'Made too much use of and finished down the field in a 12f handicap at The Curragh last time. Hood first time and back from a short break. A 10f flat winner but out of form and with a bit to prove starting over hurdles.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298665, 183349, '3', NULL, 144793, 'FR', 'Kabylia', '5', '11-5', 72.1, 'ht', '112', 327, 'K M Donoghue', 1431, 'G P Cromwell', '1st', '11/5', 3.2, 'Ran to form when second, beaten 1/2l in a 2m1f maiden hurdle at Cork last time. A bumper winner, she has been consistent over hurdles, is suited by good ground, and looks capable of winning soon.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298666, 183349, '4', NULL, 154728, 'IRE', 'Butch Coolidge', '5', '11-4', 71.65, 'NULL', '-', 1485, 'B Hayes', 4175, 'D H Kelly', NULL, NULL, NULL, 'Ran well for a long way on bumper debut but was well beaten in a 2m2f bumper at Cork last time. Needs to show more now back over hurdles.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298667, 183349, '5', NULL, 155929, 'IRE', 'Itsaworkinmaniam', '6', '11-4', 71.65, 'NULL', '-', 74, 'P T Enright', 4290, 'B McMahon', '2nd', '10/1', 11.0, 'Improved to win a maiden at Ballingarry over 3m by a length last time and returns from a short break. A 3m point winner who may be better suited to staying trips over hurdles.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298668, 183349, '6', NULL, 7356, 'IRE', 'Beir Bua', '4', '11-2', 70.75, 't', '-', 5014, 'C M Quirke', 81, 'A Slattery', NULL, NULL, NULL, "Still a touch green but ran to form when winning a mares' bumper at Wexford by 2 1/4l last time. Consistent in bumpers on good and yielding to soft ground.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298669, 183349, '7', NULL, 154624, 'IRE', 'King Bob', '4', '11-1', 70.3, 'NULL', '-', 3226, 'S D Torrens', 70, 'P J Rothwell', NULL, NULL, NULL, 'Made a poor hurdles debut when down the field in a 2m2f maiden hurdle at Cork most recently. Looks one for the future rather than immediate success.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298670, 183349, '8', NULL, 153694, 'IRE', 'Eye Of A Tiger', '5', '10-11', 68.45, 'NULL', '110', 2645, 'J J Slevin', 432, 'J P Ryan', NULL, NULL, NULL, 'Below form despite strong support when 9l third in a 2m2f maiden hurdle at Sligo last time. Proven effective between 2m and 2m1f on good ground.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298671, 183349, '9', NULL, 123114, 'IRE', 'Randall Poets Lass', '5', '10-11', 68.45, 'NULL', '-', 4905, 'B P Kennedy', 87, 'S Fahey', NULL, NULL, NULL, 'Ran poorly when beaten 7 1/4l in a Tramore handicap last time. A longstanding and frustrating maiden under both codes.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298672, 183349, '10', NULL, 155547, 'IRE', 'Ailbhe Ava', '4', '10-8', 67.1, 'NULL', '-', 69, 'S W Flanagan', 1431, 'G P Cromwell', NULL, NULL, NULL, 'Green and made mistakes on debut when well beaten in a 2m1f maiden hurdle at Wexford. Backed in the betting that day, so should be capable of better.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298673, 183349, '11', NULL, 142761, 'IRE', 'Awakening', '4', '10-8', 67.1, 'NULL', '-', 4920, 'E Walsh', 1314, 'J M Burke', NULL, '33/1', 34.0, 'Novicey jumping on debut when comfortably held in a 2m2f maiden hurdle at Sligo last time. Generally out of form, but capable of better judged on flat form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298674, 183349, '12', NULL, 155534, 'IRE', 'Miss Bella Vista', '4', '10-8', 67.1, 'NULL', '-', 3783, "P J O'Hanlon", 4169, 'D A McLoughlin', NULL, NULL, NULL, 'Green and made mistakes on debut when well beaten in a maiden hurdle at Roscommon. Should improve with the experience.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298675, 183349, '13', NULL, 137937, 'GB', 'Top Spin Lob', '4', '10-8', 67.1, 'h', '-', 6982, 'E Finegan', 4221, 'A McCann', NULL, NULL, NULL, 'Outpaced and failed to handle the surface when down the field in an 11f novice at Southwell last time. Returns from a long layoff, but showed minor ability over middle distances in the UK last summer.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298676, 183350, '1', NULL, 124420, 'IRE', 'Avondale', '5', '11-12', 75.25, 'NULL', '-', 69, 'S W Flanagan', 4190, 'B Connell', '2nd', '10/3', 4.33, 'Outpaced but finished strongly when fourth, beaten 3l, in the COLM QUINN BMW Novice Hurdle (Listed) over 2m1f at Galway last time. Steadily progressive and may prefer slightly further than 2m.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298677, 183350, '2', NULL, 104250, 'IRE', 'Catena Zapata', '7', '11-12', 75.25, 'pt', '120', 327, 'K M Donoghue', 4284, 'Ian Patrick Donoghue', NULL, NULL, NULL, 'Quickened and improved for better ground under a positive ride when winning the Conditions Hurdle at Downpatrick over 2m2f by 5 1/2l last time. Could figure here.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298678, 183350, '3', NULL, 146501, 'IRE', 'Costacurta', '5', '11-12', 75.25, 'NULL', '122', 4274, "D J O'Keeffe", 66, 'H De Bromhead', '1st', '11/4', 3.75, 'Improved from debut, with winning margin exaggerated by a faller when landing a maiden hurdle here by 17l last time. Off a short break and effective between 16f and 19f; still progressing.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298679, 183350, '4', NULL, 124696, 'IRE', 'Dysart Dasher', '8', '11-12', 75.25, 't', '117', 83, 'P Townend', 75, 'W P Mullins', NULL, NULL, NULL, 'From the yard that won this last year. Quickened clear early and won a maiden hurdle here by 3l last time. Steadily progressive and can improve again if settling.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298680, 183350, '5', NULL, 145222, 'IRE', 'Full Confession', '5', '11-12', 75.25, 'NULL', '122', 1485, 'B Hayes', 75, 'W P Mullins', NULL, NULL, NULL, 'From the yard successful in this last year. Improved as a cosy winner when suited by a positive ride down in trip, winning a maiden hurdle at Downpatrick over 2m2f by 2l last time. Progressing and will get further in time.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298681, 183350, '6', NULL, 154610, 'IRE', 'Ebony King', '4', '11-9', 73.9, 'NULL', '-', 5014, 'C M Quirke', 81, 'A Slattery', NULL, NULL, NULL, 'Made a very promising debut, showing a willing attitude when winning a maiden hurdle at Galway over 2m1f by 2 1/2l last time. Form franked and more to come; may stay a bit further than 2m.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298682, 183351, '1', NULL, 153954, 'FR', 'Liceo', '5', '11-12', 75.25, 'NULL', '106', 3783, "P J O'Hanlon", 4169, 'D A McLoughlin', NULL, '12/1', 13.0, 'Improved but not knocked about after a late error when well beaten in a maiden hurdle over 2m1f at Wexford last time; generally out of form, though progressing and capable of better judged on French flat form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298683, 183351, '2', NULL, 89910, 'GB', 'Malbas', '9', '11-12', 75.25, 'NULL', '106', 4688, 'K E Buckley', 4114, 'E Buckley', '2nd', '17/2', 9.5, 'Ran to form when scoring by a length off 100 over 2m here two starts back, benefitting from a clear passage; hampered at a key stage and flattened out when 13th beaten 22l off 106 last time; needs to improve.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298684, 183351, '3', NULL, 116759, 'IRE', 'Must Meet Cecil', '7', '11-10', 74.35, 'b', '104', 5388, 'E Staples', 4249, 'C Collins', NULL, NULL, NULL, 'Made too much use of when 7 1/2l third in a claiming hurdle over 2m2f at Sligo on latest start; steadily progressive and wears blinkers for the first time.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298685, 183351, '4', NULL, 126734, 'IRE', 'Pampar Lady', '6', '11-10', 74.35, 'NULL', '104', 327, 'K M Donoghue', 1431, 'G P Cromwell', NULL, NULL, NULL, 'Latest form emphatically franked, improving to land a handicap by 4l off 98 over 2m1f at Cork last time; progressing.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298686, 183351, '5', NULL, 130319, 'IRE', 'Smiling Bess', '6', '11-7', 73.0, 'NULL', '101', 2946, 'D Meyler', 4226, "R O'Sullivan", NULL, NULL, NULL, 'Returned to form back down in trip, just flattening out late when 7 1/2l third in a handicap hurdle over 2m2f at Cork after a break; should improve for the run.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298687, 183351, '6', NULL, 125063, 'IRE', 'Flidais', '7', '11-6', 72.55, 'NULL', '100', 435, 'D E Mullins', 432, 'J P Ryan', NULL, '12/1', 13.0, 'Never threatened and was comfortably held in a handicap hurdle over 2m1f at Sligo last time; generally out of form but has a top jockey back on board.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298688, 183351, '7', NULL, 146232, 'FR', 'Hudson', '4', '11-6', 72.55, 'NULL', '103', 4274, "D J O'Keeffe", 4328, 'Miss Ellmarie Holden', '1st', '7/1', 8.0, 'Improved slightly upped in trip when fourth, beaten 8 1/4l, in a maiden hurdle over 2m1f at Wexford last time; showed useful French flat form and may stay a bit further than 2m over hurdles.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298689, 183351, '8', NULL, 137008, 'IRE', 'Navy Guitar', '6', '11-6', 72.55, 'ht', '100', 69, 'S W Flanagan', 1137, 'A Murray', NULL, NULL, NULL, 'Improved when scoring by 3/4l off 92 over 2m2f at Sligo two starts back, quickening and holding on gamely; still green with mistakes when making too much use of last time, finishing 14th beaten 23l off 102; this demands more.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298690, 183351, '9', NULL, 35822, 'IRE', 'Brave Soldier', '5', '11-4', 71.65, 'NULL', '98', 74, 'P T Enright', 517, 'M M McNiff', NULL, NULL, NULL, 'Ran to form when 6 1/4l third in a handicap hurdle over 2m5f at Sligo on latest start; consistent.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298691, 183351, '10', NULL, 135974, 'IRE', 'Minority Interest', '5', '10-6', 66.2, 'p', '86', 5901, 'C M Hogan', 70, 'P J Rothwell', NULL, NULL, NULL, 'Below form on easier ground when needing the run, finishing down the field in a handicap hurdle over 2m4f at Killarney last time; cheekpieces applied for the first time.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298692, 183352, '1', NULL, 141771, 'IRE', 'Reiki Revolution', '5', '11-12', 75.25, 'NULL', '110', 74, 'P T Enright', 70, 'P J Rothwell', NULL, NULL, NULL, 'Ran to form when finishing 5 1/2l third in a 3m maiden hurdle here on his most recent run. Usually held up and consistent at up to 3m on decent ground, though his jumping still leaves room for improvement.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298693, 183352, '2', NULL, 155000, 'FR', 'Krishna Bellevue', '5', '11-4', 71.65, 'b', '-', 2946, 'D Meyler', 4226, "R O'Sullivan", NULL, NULL, NULL, 'Made a bad error and did not find much, running to debut form when well beaten in a 2m4f maiden hurdle at Roscommon last time. Looks more one for handicaps.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298694, 183352, '3', NULL, 155931, 'IRE', 'Messi Magic', '6', '11-4', 71.65, 'NULL', '-', 4408, 'R Deegan', 4333, 'Denis Paul Murphy', NULL, NULL, NULL, 'Yet to show real signs of ability and returns from a long absence. Needs to leave his point-to-point form behind if he is to make an impact under rules.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298695, 183352, '4', NULL, 154674, 'IRE', 'Mighty Berkshire', '5', '11-4', 71.65, 'NULL', '-', 3060, "J P O'Sullivan", 1246, 'D Queally', NULL, NULL, NULL, 'Ran to debut form when comfortably held in a 2m6f maiden hurdle at Galway last time. Effective from 2 1/2m to 3/4m, shapes like a stayer and worth a try at 3m.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298696, 183352, '5', NULL, 146024, 'IRE', 'Quantum Quest', '5', '11-4', 71.65, 'NULL', '114', 2645, 'J J Slevin', 66, 'H De Bromhead', NULL, NULL, NULL, 'From a yard that won this last year. Rallied gamely and ran to form when second, beaten 10l, in a 2m6f maiden hurdle at Downpatrick latest. Steadily progressive and generally consistent, with point form and recent effort suggesting 3m may suit.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298697, 183352, '6', NULL, 155638, 'IRE', 'Cuguilla', '5', '10-11', 68.45, 'NULL', '-', 5375, 'Conor Clarke', 432, 'J P Ryan', '1st', '40/1', 41.0, 'Green and never threatened when well beaten on debut in a 2m maiden hurdle here on her only start. Best watched for now.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298698, 183353, '1', NULL, 147391, 'IRE', 'Long Road', '6', '11-12', 75.25, 'p', '91', 3226, 'S D Torrens', 70, 'P J Rothwell', NULL, NULL, NULL, 'Never threatened but ran roughly to form when finishing down the field on handicap chase debut over 2m6f at Roscommon most recently. Generally out of form, usually held up, and has a bit to find.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298699, 183353, '2', NULL, 128673, 'IRE', 'Dawn Escape', '6', '11-7', 73.0, 'NULL', '86', 69, 'S W Flanagan', 1641, 'L Casey', NULL, NULL, NULL, 'Ran to form when stepping up in trip and grade, finishing fourth and beaten 8l in a handicap chase over 3m1f here last time.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298700, 183353, '3', NULL, 99693, 'IRE', 'Movie King', '8', '11-6', 72.55, 'pt', '85', 5771, 'Mr B M Coonan', 366, 'A J Martin', NULL, NULL, NULL, 'Ran to form and looked in need of the run when fitness gave way late, finishing 5 1/4l third in a handicap chase over 2m4f here most recently. Well treated on old form and should improve for that outing.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298701, 183353, '4', NULL, 101076, 'IRE', 'My Friend The Wind', '10', '11-6', 72.55, 'p', '85', 3199, 'G B Noonan', 418, 'E McNamara', NULL, NULL, NULL, 'Returned to form but was comfortably held in a handicap chase over 2m6f at Roscommon last time. Generally out of form but probably needs this 3m now.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298702, 183353, '5', NULL, 124679, 'IRE', 'Ballagh Star', '7', '11-4', 71.65, 'pt', '83', 4274, "D J O'Keeffe", 956, 'Mrs Y Dunleavy', NULL, NULL, NULL, 'Appeared unsuited by the drop in trip when finishing down the field in a handicap chase over 2m6f at Tramore most recently. Not out of it.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298703, 183353, '6', NULL, 110094, 'IRE', 'Thehairyfella', '10', '11-4', 71.65, 'p', '83', 3739, 'J W Kennedy', 383, 'G Elliott', '1st', '9/2', 5.5, 'Rallied gamely and scored by a head off 80 over 3m at Downpatrick three starts back. Outpaced but rallied to finish fourth beaten 8 1/4l off 84 last time, still running to form. Worth stepping back up to 3m.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298704, 183353, '7', NULL, 141413, 'GB', 'Hit The Frame', '6', '11-3', 71.2, 'bt', '82', 6618, 'A Harvey', 3560, 'J P Flavin', NULL, NULL, NULL, 'Improved up in trip with an aggressive ride in first-time blinkers, going clear but beaten 3l off 79 in a handicap chase over 3m1f at Roscommon last time. Threat if building on that.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298705, 183353, '8', NULL, 129657, 'IRE', 'Container Madness', '6', '11-2', 70.75, 'pt', '81', 2645, 'J J Slevin', 451, 'M Brassil', NULL, NULL, NULL, 'Never threatened but was ridden to see out the trip when well beaten in a handicap hurdle over 3m1f at Roscommon latest. Usually held up and should come on for that run. Of interest on chase debut.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298706, 183353, '9', NULL, 103428, 'IRE', 'Early Arrival', '10', '11-1', 70.3, 'NULL', '80', 2946, 'D Meyler', 2617, 'J Barcoe', NULL, NULL, NULL, 'Pulled up in a handicap chase over 2m6f at Tramore last time. Yet to take to chasing. May now prefer easier ground.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298707, 183353, '10', NULL, 120444, 'IRE', 'Tuff Days', '8', '10-9', 67.55, 'p', '74', 4789, 'J P Shinnick', 626, 'M Barry', NULL, NULL, NULL, 'Fell in a handicap hurdle over 3m at Wexford last time and is out of form. Remains a maiden.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298708, 183353, '11', NULL, 145991, 'IRE', 'Captain Kate', '6', '10-7', 66.65, 'p', '72', 6633, 'P Hanlon', 95, 'E Sheehy', NULL, NULL, NULL, 'Ran to form when outpaced but saw out the trip well on chase debut, comfortably held in a handicap chase over 3m1f at Roscommon last time. Generally out of form and inconsistent in a short career.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298709, 183353, '12', NULL, 146418, 'IRE', 'Tennesse Boy', '6', '10-7', 66.65, 't', '72', 74, 'P T Enright', 174, 'R Tyner', NULL, NULL, NULL, 'Pulled up in a handicap hurdle over 2m4f at Tramore last time and has yet to show anything.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298710, 183353, '13', NULL, 57825, 'IRE', 'Father Jed', '14', '10-2', 64.4, 'NULL', '67', 5467, 'D King', 432, 'J P Ryan', NULL, NULL, NULL, 'Continued in poor form when down the field in a handicap hurdle over 3m at Fairyhouse most recently. Generally out of form, returning from a long layoff, and looks regressive.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298711, 183354, '1', NULL, 124683, 'FR', 'Ho My Lord', '7', '11-12', 75.25, 'NULL', '128', 5575, 'P T Smithers', 4194, 'P Roche', NULL, NULL, NULL, 'Made mistakes but still ran to form when comfortably held in a 2m4f handicap chase at Wexford last time. Generally out of form and has a bit to find.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298712, 183354, '2', NULL, 123532, 'FR', 'Invictus Machin', '7', '11-9', 73.9, 'h', '125', 327, 'K M Donoghue', 1431, 'G P Cromwell', NULL, NULL, NULL, 'Winner of this race last year; ran to form when beaten 8 1/2l in a 2m7f handicap chase at Galway last time. Usually held up, with a top jockey back on board, but has a bit to find.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298713, 183354, '3', NULL, 125353, 'FR', 'Nouvotic', '6', '11-9', 73.9, 'h', '125', 4274, "D J O'Keeffe", 66, 'H De Bromhead', '1st', '5/2', 3.5, "From a yard that has won two of the last ten renewals. Showed determination and improved from debut when winning a beginners' chase over 2m3f at Wexford by 2 1/2l last time. Should prove competitive in handicaps.");
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298714, 183354, '4', NULL, 128695, 'IRE', 'Sea Aster', '7', '11-2', 70.75, 'p', '118', 3739, 'J W Kennedy', 383, 'G Elliott', NULL, NULL, NULL, 'Latest form franked. Improved in a weaker race and won by 2l off 117 over 3m at Perth three runs back. Unsuited by how the race unfolded when a poor fourth, beaten 34l off 120 last time. Holds only a minor chance.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298715, 183354, '5', NULL, 127009, 'IRE', 'Dorans Law', '7', '10-12', 68.9, 'p', '114', 3199, 'G B Noonan', 70, 'P J Rothwell', NULL, NULL, NULL, 'Benefited from a late faller when scoring by 5l off 109 at Wexford two starts ago. Travelled well but flattened out after a bad mistake when fourth, beaten 17l off 111 last time. On a good mark based on chase form and may prefer some ease in the ground.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298716, 183354, '6', NULL, 116130, 'FR', 'Hascoeur Clermont', '8', '10-10', 68.0, 'NULL', '112', 4636, "S O'Callaghan", 1409, 'C Coakley', NULL, NULL, NULL, 'Badly hampered by a loose horse and never competitive when comfortably held in a handicap chase at Wexford last time. Generally out of form but worth another chance.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298717, 183354, '7', NULL, 116572, 'FR', 'Bal Kauto', '8', '10-7', 66.65, 'ht', '109', 6511, 'Mr M J Kenneally', 1246, 'D Queally', NULL, NULL, NULL, 'Won easily at Galway last time. Now up 13lb but still well treated on chase form. Improved again when landing a 2m6f handicap by 5l off 104 and may have more to offer over staying trips over hurdles.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298718, 183354, '8', NULL, 94493, 'IRE', 'Fairyhill Run', '10', '10-0', 63.5, 'p', '102', 5467, 'D King', 432, 'J P Ryan', NULL, NULL, NULL, 'Fell in a handicap chase at Wexford last time. Enjoys making the running but has a bit to find.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298719, 183355, '1', NULL, 137709, 'IRE', 'Barrakilla Vage', '6', '12-0', 76.2, 'h', '-', 6692, 'Mr L P Barnett', 3837, 'Edward F Power', NULL, NULL, NULL, 'Far too keen and below debut form when finishing down the field in a bumper at Tramore last time; usually consistent; has worn a hood but still needs to learn to settle.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298720, 183355, '2', NULL, 136258, 'IRE', 'Carrig Padraig', '6', '12-0', 76.2, 'h', '-', 5346, 'Mr D M Fitzgerald', 1217, 'M P Fitzgerald', NULL, NULL, NULL, 'Ran to form but was comfortably held in a bumper at Wexford last time; plenty more required to get off the mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298721, 183355, '3', NULL, 153906, 'IRE', 'Groucho Max', '5', '12-0', 76.2, 'NULL', '-', 2508, 'Mr B J Walsh', 3836, 'Barry Walsh', NULL, NULL, NULL, 'Poor debut when well beaten in a bumper over 2m1f at Clonmel last time; off a short break; yet to show much in points or under rules.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298722, 183355, '4', NULL, 155937, 'IRE', 'Onlyforfrankie', '5', '12-0', 76.2, 'NULL', '-', 5866, 'Mr E M Nugent', 4290, 'B McMahon', '1st', '14/1', 15.0, 'Ran to form when fourth, beaten 6l, in a maiden over 3m at Ballingarry last time; off a short break; showed minor promise in points.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298723, 183355, '5', NULL, 155387, 'IRE', 'Red Oak', '5', '12-0', 76.2, 'NULL', '-', 5196, "Mr Alan O'Sullivan", 4223, 'Ciaran Murphy', NULL, NULL, NULL, 'Yard won this race last year; promising debut in a good contest when beaten 9 1/4l in a bumper over 2m2f at Galway last time; should improve for the initial experience.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298724, 183355, '6', NULL, 155941, 'IRE', 'Sonny Koufax', '6', '12-0', 76.2, 'NULL', '-', 4666, "Mr C O'Keeffe", 3499, "Conor O'Keeffe", NULL, NULL, NULL, 'Fell in a maiden over 3m at Lingstown last time; has shown little in points.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298725, 183355, '7', NULL, 131174, 'IRE', 'Cailin Deas', '7', '11-7', 73.0, 't', '-', 2459, 'Mr S Connor', 4192, 'James Andrew Fahey', NULL, NULL, NULL, 'Ran to form, doing much the best of those coming from off the pace when fourth beaten 5 1/4l in a mares bumper over 2m1f at Galway last time; consistent at 2m on decent ground in bumpers.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298726, 183355, '8', NULL, 142705, 'IRE', 'Dunbell Diva', '5', '11-7', 73.0, 'NULL', '-', 6991, 'Ms K M Ryan', 411, 'J J Hanlon', NULL, NULL, NULL, 'Affinisea mare; half-sister to Pats Gift, who was poor at 19f; probably need this initial experience.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298727, 183355, '9', NULL, 141526, 'IRE', 'Keep It Together', '7', '11-7', 73.0, 'NULL', '-', 6768, 'Mr R N Hyland', 986, 'D Buckley', NULL, NULL, NULL, 'Has no worthwhile form; has beaten only one home in four starts under rules.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298728, 183355, '10', NULL, 136174, 'IRE', 'Sellerna Bay', '5', '11-7', 73.0, 'NULL', '-', 5610, 'Mr D Doyle', 4173, 'M Fahey', NULL, NULL, NULL, 'Still green under pressure but ran to form when second, beaten 1/2l, in a mares bumper over 2m1f at Wexford last time; suited by 2m on good ground and can win a bumper.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298729, 183356, '1', '6', 151955, 'IRE', 'Extravagant', '2', '9-12', 62.55, 'NULL', '80', 5538, 'J Cleary', 1283, "A P O'Brien", '1st', '5/2', 3.5, 'Outpaced and unsuited by the drop in trip when well beaten in a 6f nursery at The Curragh on handicap debut. Generally out of form and needs at least 7f, with the potential to do better over 1m.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298730, 183356, '2', '8', 154078, 'IRE', 'Bellamano', '2', '9-11', 62.1, 'NULL', '79', 6716, 'P McGettigan', 4218, 'J P Murtagh', '2nd', '7/2', 4.5, 'Ran to form when second, beaten a neck, in a 7f auction race at Galway last time. Steadily progressive and consistent over 7-8f on easy ground. Trainer in form and looks a solid contender.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298731, 183356, '3', '4', 153176, 'IRE', 'Invincible Will', '2', '9-8', 60.75, 'NULL', '76', 861, 'G F Carroll', 1431, 'G P Cromwell', NULL, NULL, NULL, 'Conceded first run but ran to form on handicap debut when beaten 1/2l off 73 over 7f at Galway, benefitting from the drop in grade. Effective at 7f and may get 1m; looks on a good mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298732, 183356, '4', '5', 152422, 'GB', 'Clarity of Thought', '2', '9-4', 58.95, 'NULL', '72', 5052, 'M P Sheehy', 4174, "J P O'Brien", NULL, NULL, NULL, 'Ran to form when well beaten in a 7f maiden at Down Royal last time. Usually consistent, with a trainer who excels at this course. Effective over 6-7f on good or soft ground and may progress in handicaps.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298733, 183356, '5', '10', 154311, 'IRE', 'Farabove The Limit', '2', '9-0', 57.15, 'NULL', '68', 1058, 'D P McDonogh', 383, 'G Elliott', NULL, NULL, NULL, 'Possibly ran too soon when well beaten in a 7f auction race at Galway last time. Inconsistent in maidens and needs to improve to make an impact in handicaps.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298734, 183356, '6', '1', 153856, 'IRE', 'The Holy Apostle', '2', '9-0', 57.15, 'b', '68', 4343, 'L T McAteer', 168, 'B W Duke', NULL, NULL, NULL, 'Outpaced and outclassed when down the field in a 7f maiden at The Curragh most recently. Blinkers applied for the first time following a short break. Yet to build on a promising debut and bred for middle distances.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298735, 183356, '7', '2', 154125, 'IRE', 'Down The Glen', '2', '8-12', 56.2, 'NULL', '66', 826, 'S Foley', 4226, "R O'Sullivan", NULL, NULL, NULL, 'A little below form in a good 6f maiden at Naas last time. Generally consistent, with a significant jockey booking. Likely to be better suited to further than 6f in nurseries.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298736, 183356, '8', '3', 152493, 'IRE', 'Quinns Charm', '2', '8-12', 56.2, 't', '66', 6582, 'T Casey', 2655, 'M Mulvany', NULL, NULL, NULL, 'From a yard that won this race last year. Below form when stepped up in trip on final qualifying run in a Bellewstown maiden. Off a short break and bred for middle distances; improvement needed in handicaps.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298737, 183356, '9', '9', 153388, 'IRE', 'Sara La Belle', '2', '8-11', 55.75, 'h', '65', 919, 'C D Hayes', 576, 'A McGuinness', NULL, NULL, NULL, 'Returned to form when fourth, beaten 6 1/2l, in a 7f nursery at Galway last time. Wears a hood for the first time. Effective at 6-7f on good or soft ground but needs a bit more to break her maiden.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298738, 183356, '10', '7', 153358, 'IRE', 'Femme Beauty', '2', '8-10', 55.3, 'NULL', '64', 5084, 'J A Powell', 1201, 'K J Condon', NULL, NULL, NULL, 'Back to form in first-time headgear when fourth, beaten 8 1/4l, in a 7f maiden at Down Royal last time. Inconsistent over 6-7f so far, though may stay 1m.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298739, 183357, '1', '3', 152153, 'GB', 'Collecting Coin', '3', '10-0', 63.5, 'NULL', '88', 6335, 'K G Kennedy', 77, 'Mrs J Harrington', NULL, NULL, NULL, 'Ran to form with an easy win in a maiden at Galway over 7f by 3l last time; consistent over 7-8f on good and soft.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298740, 183357, '2', '2', 140817, 'GB', 'Sujet', '3', '9-13', 63.0, 'NULL', '87', 1724, 'C T Keane', 193, 'D K Weld', '2nd', '11/4', 3.75, 'Ran to form when fourth, beaten 3l in a 9f handicap at Galway latest; ridden by a top course jockey; acts on good to firm, good and soft; effective from 8-9f; consistent.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298741, 183357, '3', '4', 142743, 'IRE', 'Mathan', '3', '9-12', 62.55, 'p', '86', 6746, 'J Pietropaolo', 4174, "J P O'Brien", NULL, '5/1', 6.0, 'Ran to form when 2 1/4l third in a 9f handicap at Galway on most recent run; trained by a top course trainer; effective from 7-9f, enjoys cut and consistent.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298742, 183357, '4', '5', 135894, 'IRE', 'Refreshment', '3', '9-8', 60.75, 'b', '82', 4262, 'G M Ryan', 4173, 'M Fahey', '1st', '12/5', 3.4, 'Ran to form when second, beaten 1/4l in a 9f handicap at Galway latest; effective from 8-9f on good and soft; consistent.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298743, 183357, '5', '6', 135241, 'IRE', 'Sunriseontheboyne', '3', '9-3', 58.5, 't', '77', 6582, 'T Casey', 2655, 'M Mulvany', NULL, '25/1', 26.0, 'Outpaced, short of room and rallied when clear, finishing below form and appearing unsuited by the shorter trip when beaten 8 1/4l in a 9f handicap at Galway last time; tongue-tie first time; may prefer 9-10f; needs more in this grade.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298744, 183357, '6', '1', 136809, 'IRE', 'Dahlia Noir', '3', '9-2', 58.05, 'NULL', '76', 4805, 'P A Harnett', 3503, "Donnacha O'Brien", NULL, NULL, NULL, 'Poorly placed to challenge in a race dominated from the front when beaten 7 1/4l in a handicap here last time; effective from 8-10f, acts on any going but enjoys cut; generally consistent.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298745, 183358, '1', '2', 105290, 'IRE', 'Howyoulikethat', '8', '9-9', 61.2, 'NULL', '95', 4903, 'J M Sheridan', 196, 'Miss McLoughlin', NULL, '22/1', 23.0, 'Had too much to do in a race dominated from the front, beaten 5 1/4l in a 9f handicap at Galway last time. Generally out of form but has been running back into form after a long layoff. Effective at 1m and goes well at Killarney.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298746, 183358, '2', '1', 136534, 'IRE', 'Duckadilly', '4', '9-4', 58.95, 'NULL', '100', 4499, 'B M Coen', 4320, 'Daniel McLoughlin', '2nd', '6/1', 7.0, 'Below form when stepped up in grade on quicker ground, finishing fourth and beaten 6l in the Brownstown Stakes (Group 3) over 7f at Leopardstown last time. Effective at 7-8f.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298747, 183358, '3', '7', 131963, 'IRE', 'Evening Blossom', '4', '9-4', 58.95, 't', '99', 1058, 'D P McDonogh', 4174, "J P O'Brien", NULL, NULL, NULL, 'Ran below form when beaten 8l in a 9f handicap at Galway last time. Usually consistent and from a top course trainer. Acts on good and soft ground; progressive but now facing a tougher mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298748, 183358, '4', '6', 131200, 'IRE', 'Soft Winds', '4', '9-4', 58.95, 'p', '91', 5052, 'M P Sheehy', 4174, "J P O'Brien", NULL, NULL, NULL, 'Made too much use of and finished 8l behind in the Hurry Harriet Stakes (Listed) over 9f at Gowran Park last time. From a top course trainer, may need some cut, but looks vulnerable at Group/Listed level.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298749, 183358, '5', '9', 122331, 'IRE', 'Thalara', '5', '9-4', 58.95, 'NULL', '95', 4477, 'A J Slattery', 66, 'H De Bromhead', NULL, '8/1', 9.0, 'Improved when dropped back in trip, finishing 3 1/4l third in the Kooyonga Stakes (Listed) at Navan last time. Steadily progressive and returning from a short break, effective at 8-10f and capable at Listed level.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298750, 183358, '6', '3', 154486, 'IRE', 'Barbizon', '3', '9-3', 58.5, 'NULL', '-', 1724, 'C T Keane', 419, 'J J Murphy', NULL, '10/1', 11.0, 'Keen but improved for his debut experience to win the Conditions Race here by 2 1/4l last time. With a top course jockey booked, effective at 1m and has more to come.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298751, 183358, '7', '8', 152150, 'GB', 'Ben Lawers', '3', '9-3', 58.5, 't', '-', 826, 'S Foley', 77, 'Mrs J Harrington', NULL, NULL, NULL, 'Ran to form when 3l third in a 9f maiden at Leopardstown last time. Steadily progressive and consistent over 8-9f on good ground, but needs to settle better.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298752, 183358, '8', '4', 144134, 'IRE', 'Expanded', '3', '9-3', 58.5, 'NULL', '113', 4262, 'G M Ryan', 1283, "A P O'Brien", '1st', '12/5', 3.4, 'From a yard that has won 3 of the last 5 runnings of this race. Disappointing when down the field in the Irish 2,000 Guineas (Group 1) at The Curragh last time. Returning from a short break and yet to show the ability displayed as a 2yo.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298753, 183358, '9', '5', 9748, 'IRE', 'Mississippi River', '3', '9-3', 58.5, 'b', '98', 919, 'C D Hayes', 1283, "A P O'Brien", NULL, NULL, NULL, 'From a yard that has won 3 of the last 5 renewals. Below form when beaten 4 1/2l in a 9f handicap at Galway last time. Usually consistent, effective over 8-9f and acts on any ground, though can be frustrating.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298754, 183358, '10', '11', 137000, 'GB', 'Fiery Lucy', '3', '8-12', 56.2, 'NULL', '103', 861, 'G F Carroll', 1431, 'G P Cromwell', NULL, NULL, NULL, 'Forced wide from a poor draw when down the field in the Corrib Fillies Stakes (Listed) over 7f at Galway last time. With a top jockey back on board, she acts on firm, good and soft, generally consistent at around 1m, and can bounce back.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298755, 183358, '11', '10', 154510, 'IRE', 'Queen Of The Bogs', '3', '8-12', 56.2, 'NULL', '-', 4244, 'N M Crosse', 419, 'J J Murphy', NULL, NULL, NULL, 'Quickened clear comfortably and improved for her debut experience when winning a 9f maiden at The Curragh by 5l last time. Effective at 9-10f and worth a step up in grade.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298756, 183359, '1', '16', 130895, 'IRE', 'Shelbourne', '4', '10-0', 63.5, 'NULL', '70', 919, 'C D Hayes', 4191, 'M Hassett', NULL, '25/1', 26.0, 'Forced wide from a poor draw when beaten 8l in a handicap over 7f at Naas last time; effective at 7-8f.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298757, 183359, '2', '10', 131233, 'GB', 'Star Mind', '4', '10-0', 63.5, 'NULL', '70', 6771, 'Nicola Burns', 4301, "Gerard O'Leary", NULL, NULL, NULL, 'Did it cosily, back in form when landing a handicap by 1/2l off 62 over 7f at Naas last time in a strongly run race; effective at 7-8f; remains well treated on old UK form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298758, 183359, '3', '5', 103164, 'GB', 'Chavajod', '7', '9-13', 63.0, 'v', '69', 1735, 'R Coakley', 3235, 'D P Coakley', '1st', '15/2', 8.5, 'Returned to form under positive handling when beaten 1/2l off 68 over 9f at Galway last time; best at 1m; inconsistent veteran.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298759, 183359, '4', '7', 105510, 'IRE', 'Darkdeserthighway', '7', '9-11', 62.1, 'b', '67', 927, 'L F Roche', 2370, "M O'Callaghan", NULL, '14/1', 15.0, 'Below form when beaten 10l in a handicap at The Curragh last time; generally consistent at 1m on good ground; holds no secrets from the handicapper.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298760, 183359, '5', '14', 113595, 'IRE', 'Secret Magician', '6', '9-11', 62.1, 'pt', '67', 4805, 'P A Harnett', 4191, 'M Hassett', NULL, NULL, NULL, 'Ran to form when beaten 2l off 67 over 7f at Naas last time; effective at 6-7f, unproven over further.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298761, 183359, '6', '15', 99532, 'IRE', 'Speckled Meadow', '8', '9-11', 62.1, 'NULL', '67', 5811, 'M W Hassett', 3082, 'Don Browne', NULL, NULL, NULL, 'Ran to current form when beaten 3 1/4l off 68 over 9f at Galway last time; effective at 7-8f, best with cut; handicapper finally relenting.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298762, 183359, '7', '3', 133342, 'GB', 'Still She Blooms', '4', '9-9', 61.2, 'h', '65', 332, 'R C Colgan', 4363, 'C Timmons', NULL, NULL, NULL, 'Quickened clear early and scored by 3l off 57 here penultimate start; effective 7-9f; can do better under a slightly more patient ride at 1m.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298763, 183359, '8', '18', 111323, 'IRE', 'Linger For Longer', '6', '9-7', 60.3, 'NULL', '63', 6543, "D S O'Sullivan", 194, 'A Leahy', NULL, NULL, NULL, 'Outclassed up in grade when beaten 6 1/2l in a Rated Race over 7f at Limerick last time; effective at 7f; out of form in 2025.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298764, 183359, '9', '13', 133086, 'IRE', 'Nedita', '4', '9-7', 60.3, 'NULL', '63', 4343, 'L T McAteer', 1083, 'D Marnane', NULL, '14/1', 15.0, 'Below form when beaten 4l off 65 over 7f at Naas last time; top jockey back on board; effective at 1m but yet to prove as effective on turf.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298765, 183359, '10', '17', 137120, 'IRE', 'No Such Thing', '3', '9-7', 60.3, 'v', '69', 6977, 'C J Worrell', 4226, "R O'Sullivan", NULL, NULL, NULL, 'Too keen lit up by first-time visor when 13l third in a maiden here most recently; acts on good and soft; inconsistent.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298766, 183359, '11', '9', 152403, 'IRE', 'Senti Qua', '3', '9-7', 60.3, 'p', '69', 1724, 'C T Keane', 1201, 'K J Condon', NULL, NULL, NULL, 'Hampered early and had too much to do, improved in first-time cheekpieces when beaten 1/2l off 65 over 7f at Dundalk last time; top course jockey; consistent at 7-8f.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298767, 183359, '12', '8', 136674, 'IRE', 'Zaraahmando', '3', '9-7', 60.3, 'NULL', '69', 4477, 'A J Slattery', 81, 'A Slattery', '2nd', '11/1', 12.0, 'Scored by 2l off 61 over 7f at Fairyhouse penultimate start; below form off a revised mark when beaten 15l off 69 last time; effective at 7f; stiff mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298768, 183359, '13', '11', 137940, 'GB', 'Vegas Muse', '3', '9-5', 59.4, 'p', '67', 826, 'S Foley', 77, 'Mrs J Harrington', NULL, NULL, NULL, 'Did plenty early lit up by blinkers when beaten 9l in a handicap at Galway last time; in good form prior; effective at 7-8f; generally consistent but frustrating.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298769, 183359, '14', '6', 142129, 'GB', 'Brandon Creek', '3', '9-4', 58.95, 'NULL', '66', 5538, 'J Cleary', 4301, "Gerard O'Leary", NULL, NULL, NULL, 'Blew the start and met trouble when down the field in a handicap over 12f at Galway last time; generally out of form but trainer in form; effective 8-12f on good or soft; bit more to come.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298770, 183359, '15', '12', 142390, 'IRE', 'Touted Plan', '3', '9-2', 58.05, 'NULL', '64', 861, 'G F Carroll', 1092, 'J G Murphy', NULL, NULL, NULL, 'Improved with strong pace and stiff track when beaten a nose off 61 over 7f at Naas last time; best on sound surface; effective 7-8f; bit more to come.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298771, 183359, '16', '4', 125441, 'GB', 'Daonethatgotaway', '5', '10-2', 64.4, 'pt', '72', 2070, 'Reserve 1', 4173, 'M Fahey', NULL, '16/1', 17.0, 'Scored by 3/4l off 65 at Bellewstown three starts back; outpaced and poorly placed when tenth beaten 8l off 72 last time; effective 8-10f; generally consistent.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298772, 183359, '17', '2', 131973, 'IRE', 'Nakasero', '4', '10-1', 63.95, 't', '71', 1729, 'Reserve 2', 66, 'H De Bromhead', NULL, '12/1', 13.0, 'Made too much use of up in grade when down the field in a handicap over 7f at Naas most recently; usually consistent; effective on good to firm, good, or soft ground; generally consistent at around 1m, can bounce back down in grade.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298773, 183359, '18', '1', 130587, 'IRE', 'Alto Sax', '4', '9-3', 58.5, 'p', '59', 2564, 'Reserve 3', 1756, 'Peter Fahey', NULL, NULL, NULL, 'Below form when well beaten in a handicap over 10f at Ballinrobe latest; cheekpieces first time; effective 7-10f on good ground, may not handle easier going; slow starts an issue.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298774, 183360, '1', '10', 130799, 'GB', 'Comic Book', '4', '10-0', 63.5, 'p', '93', 6335, 'K G Kennedy', 77, 'Mrs J Harrington', NULL, NULL, NULL, 'Had every chance but was outclassed and possibly did not stay when well beaten in the Stanerra Stakes (Group 3) at Fairyhouse last time. Generally out of form and has yet to convince with stamina over 14f.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298775, 183360, '2', '7', 129790, 'IRE', 'Mo Ghille Mar', '4', '9-13', 63.0, 'p', '92', 826, 'S Foley', 77, 'Mrs J Harrington', NULL, NULL, NULL, 'Won by 3 1/4l off 84 over 1m5f at Down Royal two starts ago. Ran to form when tenth, beaten 7 1/4l off 92 last time. Top jockey back on board; effective 12-14f on a sound surface but the handicapper may have caught up.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298776, 183360, '3', '3', 118202, 'IRE', 'Mon Coeur', '9', '9-6', 59.85, 'NULL', '85', 861, 'G F Carroll', 1092, 'J G Murphy', NULL, NULL, NULL, 'Met trouble early but ran to his best when second, beaten 5l, in a handicap over 2m1f at Galway last time. Top jockey returns. Effective 12-16f, best with cut in the ground, and goes well at Galway.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298777, 183360, '4', '5', 131751, 'IRE', 'Brosna Town', '4', '9-5', 59.4, 't', '84', 919, 'C D Hayes', 193, 'D K Weld', NULL, NULL, NULL, 'Promising hurdle debut but comfortably held in a maiden hurdle over 2m1f at Galway last time. Trainer in form. Effective 12-14f on good ground and all-weather on the flat, but looks on a stiff enough mark.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298778, 183360, '5', '9', 132046, 'GB', 'Granite Bay', '4', '9-4', 58.95, 'NULL', '83', 4244, 'N M Crosse', 672, 'J P Fahey', NULL, NULL, NULL, 'Made too much use of the running and set it up for a closer when comfortably held in a Rated Race at Fairyhouse last time. In good form before that; effective 12-14f and probably best with some give in the ground; could progress again.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298779, 183360, '6', '4', 133450, 'IRE', 'Ragmans Corner', '6', '9-4', 58.95, 'NULL', '83', 1724, 'C T Keane', 521, 'G Keane', NULL, NULL, NULL, 'Improved up in trip for a cosy win, scoring by 2l off 73 at Navan in June. Hampered mid race but aided by leaders racing early, ran to form when second, beaten 1 1/2l off 115 last time. Top course jockey booked and looks well treated on flat form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298780, 183360, '7', '8', 152162, 'IRE', 'Kilmeaden', '3', '9-1', 57.6, 'p', '89', 4262, 'G M Ryan', 3503, "Donnacha O'Brien", '1st', '9/2', 5.5, 'Back to form when showing a willing attitude to land a handicap by a neck off 82 over 12f at Galway last time. Effective at 12f on good and soft ground. Still mileage in his mark on maiden form and may have more to offer over staying trips.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298781, 183360, '8', '11', 146219, 'IRE', 'Autumn Twist', '4', '9-0', 57.15, 'p', '79', 4903, 'J M Sheridan', 4193, 'D Hogan', NULL, NULL, NULL, 'Ran to form but challenged too early off a strong pace when beaten 8l in a handicap hurdle over 2m1f at Galway last time. Had been in good form beforehand and is progressive in both codes.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298782, 183360, '9', '1', 126226, 'IRE', 'Pinot Gris', '5', '9-0', 57.15, 'vt', '79', 5426, 'R Whearty', 1431, 'G P Cromwell', NULL, NULL, NULL, 'Poorly placed and never threatened on flat return, needing the run when beaten 9 1/4l in a 2m handicap at The Curragh last time. Wears a visor for the first time. Off a short break. Effective 12-16f on good and soft ground, with scope on jumps form.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298783, 183360, '10', '6', 155298, 'FR', 'Bibe Mus', '3', '8-10', 55.3, 'NULL', '84', 1058, 'D P McDonogh', 4226, "R O'Sullivan", NULL, NULL, NULL, 'Ran to form when appreciating the step up in trip on stable debut, beaten 4 1/4l in a 12f handicap at Galway last time. Effective 10-12f and likely to show more for the new yard over staying trips.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298784, 183360, '11', '2', 112684, 'IRE', 'Chutzpal', '6', '8-7', 53.95, 'b', '72', 5811, 'M W Hassett', 66, 'H De Bromhead', '2nd', '12/1', 13.0, 'Ran to form when beaten 4l off 70 at Wolverhampton last time. Effective 12-14f on good ground and all-weather.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298785, 183361, '1', '11', 135596, 'IRE', 'Empress Alma', '4', '10-0', 63.5, 'NULL', '70', 5426, 'R Whearty', 1431, 'G P Cromwell', NULL, NULL, NULL, 'Unsuited by how the race developed on a quick return but not disgraced when beaten 10l in a Galway handicap last time. Usually consistent, held up, and effective from middle to staying distances on good or soft ground.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298786, 183361, '2', '2', 131438, 'IRE', 'Gangster Granny', '4', '9-13', 63.0, 'b', '69', 6335, 'K G Kennedy', 77, 'Mrs J Harrington', NULL, NULL, NULL, 'Below form and finished down the field in a 12f Galway handicap most recently. Generally out of form and wears blinkers for the first time. Effective at 12-14f on good or soft ground but form is regressing and needs an easier task.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298787, 183361, '3', '9', 130136, 'IRE', 'Miss Gitana', '4', '9-12', 62.55, 'NULL', '68', 5519, 'J Kearney', 383, 'G Elliott', NULL, NULL, NULL, 'Well backed when winning by 1/2l off 65 over 2m at Tramore in July. Stopped quickly and ran to form when eighth, beaten 14l off 97 last time.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298788, 183361, '4', '12', 140789, 'IRE', 'Atheneum', '4', '9-11', 62.1, 'p', '67', 6724, 'S Coen', 419, 'J J Murphy', NULL, '20/1', 21.0, 'Below form when dropped in trip and finished down the field in a 12f Galway handicap most recently. Cheekpieces on first time. Effective 12-14f on good or soft ground. Still early days and could bounce back.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298789, 183361, '5', '1', 111425, 'IRE', 'Beautiful Chaos', '7', '9-11', 62.1, 'p', '67', 5739, 'S R Markey', 4226, "R O'Sullivan", NULL, NULL, NULL, 'Ran to form when stepped up in trip, beaten 4l off 65 at Galway last time. Effective at 12-14f. A veteran on a long losing run but in good heart.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298790, 183361, '6', '10', 117936, 'GER', 'Ehteyat', '6', '9-10', 61.65, 'b', '66', 4805, 'P A Harnett', 4383, 'Michael Flannery', NULL, '14/1', 15.0, 'Denied a clear run at a key stage and had too much to do when beaten 5l in a Galway handicap last time. Effective 14-16f. Has dropped to a very attractive mark on UK form and should go close if building on latest run.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298791, 183361, '7', '14', 138139, 'IRE', 'Makaiah', '4', '9-10', 61.65, 'NULL', '66', 6771, 'Nicola Burns', 4301, "Gerard O'Leary", '2nd', '12/1', 13.0, 'Stable won this last year. Too keen and wide when comfortably held in a 1m7f Leopardstown handicap last time but had been in good form before. Consistent at 13-16f on good ground. Can bounce back but little leeway from the handicapper.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298792, 183361, '8', '8', 127615, 'IRE', 'Lady Kai', '5', '9-8', 60.75, 'p', '64', 5084, 'J A Powell', 4226, "R O'Sullivan", NULL, NULL, NULL, 'Unseated rider in a 1m7f Leopardstown handicap latest. Consistent at 12-14f on a sound surface. Big chance up in trip.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298793, 183361, '9', '5', 152149, 'GB', 'Bear Creek', '3', '9-7', 60.3, 'p', '72', 5811, 'M W Hassett', 4174, "J P O'Brien", NULL, NULL, NULL, 'Ideally suited by trip when winning by 2l off 61 over 1m5f at Down Royal penultimate start. Forced wide but ran to form up in grade when third, beaten 4l off 71 last time. From a top course trainer, effective 11-13f on good or yielding, and steadily progressing.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298794, 183361, '10', '3', 140850, 'IRE', 'Eagles Dream', '3', '9-4', 58.95, 'p', '69', 6726, 'J S Dalton', 419, 'J J Murphy', NULL, NULL, NULL, 'Below form on softer ground when finishing down the field in a 12f Galway handicap last time. Had been in good form prior. Effective at 10-12f on good or yielding ground. Consistent but current mark looks about right.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298795, 183361, '11', '6', 88003, 'GB', 'Ellaat', '9', '9-4', 58.95, 'NULL', '60', 6746, 'J Pietropaolo', 3242, "Ian O'Connor", NULL, '50/1', 51.0, 'Had too much to do after meeting trouble at a key stage when beaten 9l in a Galway handicap last time. Effective at 12-14f on the flat, with best efforts when the ground has cut.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298796, 183361, '12', '4', 147499, 'IRE', 'Wertpol', '3', '9-4', 58.95, 'NULL', '69', 6716, 'P McGettigan', 4218, 'J P Murtagh', '1st', '5/1', 6.0, 'Outpaced and below form on handicap debut, beaten 6l over 8f at Leopardstown last time. Usually consistent, with trainer in form. Returns from a short break and looks in need of a step up from 8-10f. Has been well backed last twice and mark looks fair.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298797, 183361, '13', '7', 141748, 'IRE', 'Decorated Elle', '4', '9-1', 57.6, 'NULL', '57', 6543, "D S O'Sullivan", 737, "D O'Sullivan", NULL, NULL, NULL, 'Outpaced, needed the run, and appeared unsuited by the drop in trip when finishing down the field in an 8f Curragh handicap most recently. Usually consistent but needs a return to longer distances. Should come on for reappearance but has a bit to prove.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298798, 183361, '14', '13', 76649, 'IRE', 'Youllfindandsee', '10', '8-7', 53.95, 'pt', '49', 5801, 'R M Mulligan', 3242, "Ian O'Connor", NULL, '50/1', 51.0, 'Pulled up in a maiden hurdle over 2m4f at Cork last time. Needs to prove ability remains after a long layoff.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298799, 183362, '1', '1', 105025, 'GB', 'Gentleman Joe', '7', '12-0', 76.2, 't', '92', 5874, 'Mr J H Williamson', 66, 'H De Bromhead', NULL, NULL, NULL, 'Improved again when appreciating the fast ground, winning the Conditions Race (Amateurs) at Leopardstown over 1m7f by 1/2l last time. Acts on any surface but seems to prefer faster ground, and is a progressive stayer on the flat.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298800, 183362, '2', '8', 103956, 'IRE', 'Enniskerry', '11', '11-7', 73.0, 't', '89', 3355, 'Mr F Maguire', 4190, 'B Connell', '2nd', '11/2', 6.5, 'Ran to form when well beaten in the Galway Hurdle (G3) over 2m at Galway last time. Had been in good form prior but has a bit to find here.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298801, 183362, '3', '9', 97567, 'IRE', 'Run For Oscar', '10', '11-7', 73.0, 'NULL', '105', 5204, 'Mr D McGill', 188, 'C Byrnes', NULL, NULL, NULL, 'Ran to form in the contest he won in 2022, finishing fourth and beaten 1 1/4l in a 2m2f handicap at Newmarket last time. Returning from a long layoff; a veteran thorough stayer who was in good form when last seen. This is a probable prep for the Cesarewitch.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298802, 183362, '4', '2', 90383, 'FR', 'Appian Way', '9', '11-4', 71.65, 'NULL', '47', 5499, 'Ms A Power', 623, 'Ms M Flynn', NULL, NULL, NULL, 'Disappointing on flat return when finishing down the field in a 2m maiden at Tramore most recently. Out of form in both codes.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298803, 183362, '5', '5', 147433, 'IRE', 'He Who Dares', '4', '11-4', 71.65, 'NULL', '-', 7021, 'Miss N Lockhead Anderson', 2015, 'S Curling', NULL, NULL, NULL, 'Made a modest debut when well beaten in a 2m maiden at Tramore last time. Trainer is in form, but poor over hurdles and will need more time on the flat.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298804, 183362, '6', '7', 131835, 'IRE', 'Mont St Michel', '4', '11-4', 71.65, 'NULL', '95', 6859, 'Mr P J Smullen', 1283, "A P O'Brien", NULL, NULL, NULL, 'Probably made his move too soon when a 5l third in a 12f maiden at Galway on his most recent run. Effective from 12f to 14f, he has shown a good level of form and should be winning soon.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298805, 183362, '7', '4', 109767, 'IRE', 'Simpletwistoffaith', '8', '11-4', 71.65, 'NULL', '-', 5184, "Mr K O'Neill", 420, "J F O'Neill", NULL, '100/1', 101.0, 'Poor flat debut when down the field in a 12f maiden at Galway most recently. Generally out of form and regressive over jumps prior to that start; can only be watched at present.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298806, 183362, '8', '3', 127055, 'IRE', 'Sorrentino', '7', '11-4', 71.65, 'h', '-', 158, 'Mr P W Mullins', 75, 'W P Mullins', '1st', '12/5', 3.4, 'Yard has won 3 of the last 8 runnings of this race. Very promising debut when second, beaten 1/2l, in the Conditions Race (Amateurs) over 1m5f at Listowel most recently. Off a short break, he is a bumper winner with more to come and should do better over 2m.');
INSERT INTO racecard_details (id, race_id, horse_number, Draw, Horse_ID, Country, Name, Age, weight_uk, weight, gears, Horse_rate, jockey_ID, jockey, trainer_ID, trainer, fav, odds, odds_decimal, Timeform_comments) VALUES (298807, 183362, '9', '6', 101306, 'IRE', 'Tullyhogue Fort', '9', '11-4', 71.65, 't', '42', 857, "Mr P J O'Neill", 420, "J F O'Neill", NULL, NULL, NULL, 'Unseated in a 2m6f handicap chase at Roscommon last time. Consistent but has a poor strike rate.');
